const selectedEpisodeStorageKey = "dialecticore.selectedEpisodeId.v1";

function readSelectedEpisodeId(): string | null {
  if (typeof window === "undefined") {
    return null;
  }
  try {
    const value = window.localStorage.getItem(selectedEpisodeStorageKey)?.trim();
    return value || null;
  } catch {
    return null;
  }
}

function writeSelectedEpisodeId(episodeId: string | null) {
  if (typeof window === "undefined") {
    return;
  }
  try {
    if (episodeId) {
      window.localStorage.setItem(selectedEpisodeStorageKey, episodeId);
    } else {
      window.localStorage.removeItem(selectedEpisodeStorageKey);
    }
  } catch {
    // Selection persistence is a convenience, not a production requirement.
  }
}

