function selectableVoiceProfiles(
  profiles: VoiceProfile[],
  endpoints: VoiceboxEndpoint[],
  preferredProfileId?: string | null,
): VoiceProfile[] {
  const endpointById = new Map(
    endpoints.map((endpoint) => [endpoint.id, endpoint]),
  );
  const seen = new Set<string>();
  return [...profiles]
    .filter((profile) => {
      const endpoint = endpointById.get(profile.voicebox_endpoint_id);
      return (
        profile.id === preferredProfileId ||
        (profile.enabled &&
          Boolean(endpoint?.enabled) &&
          endpoint?.health_status !== "unhealthy")
      );
    })
    .sort((left, right) => {
      const leftPreferred = left.id === preferredProfileId ? 0 : 1;
      const rightPreferred = right.id === preferredProfileId ? 0 : 1;
      const leftEndpoint = endpointById.get(left.voicebox_endpoint_id);
      const rightEndpoint = endpointById.get(right.voicebox_endpoint_id);
      const leftNative =
        leftEndpoint?.adapter_type === "b1_voice_stream" ? 0 : 1;
      const rightNative =
        rightEndpoint?.adapter_type === "b1_voice_stream" ? 0 : 1;
      return (
        leftPreferred - rightPreferred ||
        leftNative - rightNative ||
        left.name.localeCompare(right.name) ||
        left.id.localeCompare(right.id)
      );
    })
    .filter((profile) => {
      const key = `${profile.language.toLowerCase()}::${voiceProfileSelectionLabel(profile).toLowerCase()}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function voiceProfileSelectionLabel(profile: VoiceProfile): string {
  return profile.name.replace(/\s+\(B1 [^)]+\)$/i, "").trim();
}

