async function fetchJson<T>(path: string): Promise<T> {
  const response = await fetch(`${apiBaseUrl}${path}`, {
    headers: requestHeaders(),
  });
  if (!response.ok) {
    throw await apiRequestError(response);
  }
  return response.json();
}

async function postJson<T>(path: string, payload?: unknown): Promise<T> {
  const response = await fetch(`${apiBaseUrl}${path}`, {
    method: "POST",
    headers: requestHeaders(Boolean(payload)),
    body: payload ? JSON.stringify(payload) : undefined,
  });
  if (!response.ok) {
    throw await apiRequestError(response);
  }
  return response.json();
}

async function postJsonWithTimeout<T>(
  path: string,
  payload: unknown,
  timeoutMs: number,
  baseUrl = apiBaseUrl,
): Promise<T> {
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${baseUrl}${path}`, {
      method: "POST",
      headers: requestHeaders(true),
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
    if (!response.ok) {
      throw await apiRequestError(response);
    }
    return response.json();
  } catch (error) {
    if (error instanceof DOMException && error.name === "AbortError") {
      throw new Error(
        "Provider request timed out before the browser received a response.",
      );
    }
    throw error;
  } finally {
    window.clearTimeout(timeout);
  }
}

function localDevApiBaseUrlForLongAction(): string {
  if (apiBaseUrl) {
    return apiBaseUrl;
  }
  if (
    window.location.hostname === "127.0.0.1" &&
    window.location.port === "5173"
  ) {
    return "http://127.0.0.1:8000";
  }
  if (
    window.location.hostname === "localhost" &&
    window.location.port === "5173"
  ) {
    return "http://127.0.0.1:8000";
  }
  return apiBaseUrl;
}

async function putJson<T>(path: string, payload?: unknown): Promise<T> {
  const response = await fetch(`${apiBaseUrl}${path}`, {
    method: "PUT",
    headers: requestHeaders(Boolean(payload)),
    body: payload ? JSON.stringify(payload) : undefined,
  });
  if (!response.ok) {
    throw await apiRequestError(response);
  }
  return response.json();
}

async function patchJson<T>(path: string, payload?: unknown): Promise<T> {
  const response = await fetch(`${apiBaseUrl}${path}`, {
    method: "PATCH",
    headers: requestHeaders(Boolean(payload)),
    body: payload ? JSON.stringify(payload) : undefined,
  });
  if (!response.ok) {
    throw await apiRequestError(response);
  }
  return response.json();
}

async function deleteJson<T = void>(path: string): Promise<T> {
  const response = await fetch(`${apiBaseUrl}${path}`, {
    method: "DELETE",
    headers: requestHeaders(),
  });
  if (!response.ok) {
    throw await apiRequestError(response);
  }
  if (response.status === 204) {
    return undefined as T;
  }
  return (await response.json()) as T;
}

async function fileToBase64(file: File): Promise<string> {
  const bytes = new Uint8Array(await file.arrayBuffer());
  const chunkSize = 0x8000;
  let binary = "";
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    binary += String.fromCharCode(
      ...bytes.subarray(offset, offset + chunkSize),
    );
  }
  return btoa(binary);
}

