function useLiveStatusEvents(
  authSession: BrowserAuthSession,
  enabled = true,
): LiveStatusStreamState {
  const [state, setState] = React.useState<LiveStatusStreamState>({
    status: "connecting",
    events: [],
    error: null,
  });

  React.useEffect(() => {
    if (!enabled) {
      return;
    }
    let cancelled = false;
    const controller = new AbortController();

    async function connect() {
      setState((current) => ({
        ...current,
        status: "connecting",
        error: null,
      }));
      try {
        const response = await fetch(
          `${apiBaseUrl}/api/v1/system/events?interval_seconds=5&audit_limit=5`,
          {
            headers: requestHeaders(),
            signal: controller.signal,
          },
        );
        if (!response.ok) {
          throw new Error(`Live stream failed: ${response.status}`);
        }
        if (!response.body) {
          throw new Error("Live stream body is unavailable.");
        }
        setState((current) => ({ ...current, status: "open", error: null }));
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        while (!cancelled) {
          const { done, value } = await reader.read();
          if (done) {
            break;
          }
          buffer += decoder.decode(value, { stream: true });
          const parsed = parseSseBuffer(buffer);
          buffer = parsed.remainder;
          for (const event of parsed.events) {
            if (cancelled) {
              break;
            }
            setState((current) => ({
              status: "open",
              error: null,
              events: [event, ...current.events].slice(0, 6),
            }));
          }
        }
      } catch (error) {
        if (
          !cancelled &&
          !(error instanceof DOMException && error.name === "AbortError")
        ) {
          setState((current) => ({
            ...current,
            status: "disconnected",
            error:
              error instanceof Error
                ? error.message
                : "Live stream disconnected.",
          }));
        }
      }
    }

    void connect();
    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [authSession, enabled]);

  return state;
}

