function parseSseBuffer(buffer: string): {
  events: LiveStatusEvent[];
  remainder: string;
} {
  const events: LiveStatusEvent[] = [];
  let remainder = buffer;
  let boundary = remainder.indexOf("\n\n");
  while (boundary >= 0) {
    const block = remainder.slice(0, boundary);
    remainder = remainder.slice(boundary + 2);
    const data = block
      .split("\n")
      .filter((line) => line.startsWith("data:"))
      .map((line) => line.slice(5).trimStart())
      .join("\n");
    if (data) {
      try {
        const parsed = JSON.parse(data) as LiveStatusEvent;
        if (parsed.schema_version === "system_status_event.v1") {
          events.push(parsed);
        }
      } catch {
        // Ignore malformed stream frames and continue consuming later events.
      }
    }
    boundary = remainder.indexOf("\n\n");
  }
  return { events, remainder };
}

