function EpisodePicker(props: {
  episodes: EpisodeSummary[];
  includeArchived: boolean;
  projects: Project[];
  selectedEpisodeId: string | null;
  isLoading: boolean;
  error: unknown;
  onArchiveVisibilityChange: (visible: boolean) => void;
  onNewEpisode: () => void;
  onSelect: (episodeId: string) => void;
}) {
  const projectById = React.useMemo(
    () => new Map(props.projects.map((project) => [project.id, project])),
    [props.projects],
  );
  const selectedEpisode = props.selectedEpisodeId
    ? props.episodes.find((episode) => episode.id === props.selectedEpisodeId) ??
      null
    : null;
  const currentEpisodes = props.episodes.filter(
    (episode) => !["COMPLETED", "CANCELLED"].includes(episode.status),
  );
  const archivedEpisodes = props.episodes.filter((episode) =>
    ["COMPLETED", "CANCELLED"].includes(episode.status),
  );
  const selectedEpisodeIsArchived = Boolean(
    selectedEpisode &&
      ["COMPLETED", "CANCELLED"].includes(selectedEpisode.status),
  );
  const archiveVisible = props.includeArchived || selectedEpisodeIsArchived;
  const recentEpisodes = currentEpisodes.slice(0, 6);

  return (
    <section className="episodePicker" aria-label="Episode selection">
      <div className="episodePickerHeader">
        <div>
          <span>Working episode</span>
          <strong>{selectedEpisode?.title ?? "No episode selected"}</strong>
        </div>
        <span className="statusPill">{selectedEpisode?.status ?? "new"}</span>
      </div>
      <label className="field">
        <span>Episode</span>
        <select
          disabled={props.isLoading || props.episodes.length === 0}
          value={selectedEpisode?.id ?? ""}
          onChange={(event) => props.onSelect(event.target.value)}
        >
          <optgroup label="Current production">
            {currentEpisodes.map((episode) => (
              <option key={episode.id} value={episode.id}>
                {episode.title} - {episode.status}
              </option>
            ))}
          </optgroup>
          {archiveVisible ? (
            <optgroup label="Archive">
              {archivedEpisodes.map((episode) => (
                <option key={episode.id} value={episode.id}>
                  {episode.title} - {episode.status}
                </option>
              ))}
            </optgroup>
          ) : null}
        </select>
      </label>
      <div className="episodePickerActions">
        <button
          className="primaryButton compact"
          onClick={props.onNewEpisode}
          type="button"
        >
          <Plus size={16} />
          New Episode
        </button>
        <button
          aria-pressed={archiveVisible}
          className="secondaryButton compact"
          disabled={selectedEpisodeIsArchived || props.isLoading}
          onClick={() => props.onArchiveVisibilityChange(!archiveVisible)}
          title={
            selectedEpisodeIsArchived
              ? "Select a current episode before hiding the archive"
              : "Show or hide completed and cancelled episodes"
          }
          type="button"
        >
          <History size={16} />
          {archiveVisible ? "Hide archive" : "Show archive"}
          {archiveVisible ? <span>{archivedEpisodes.length}</span> : null}
        </button>
      </div>
      {props.error ? (
        <p className="errorText compact">{String(props.error)}</p>
      ) : null}
      {recentEpisodes.length > 0 ? (
        <div className="episodeQuickList" aria-label="Recent episodes">
          {recentEpisodes.map((episode) => (
            <button
              className={`episodeQuickItem ${episode.id === selectedEpisode?.id ? "selected" : ""}`}
              key={episode.id}
              onClick={() => props.onSelect(episode.id)}
              type="button"
            >
              <span>{episode.title}</span>
              <small>
                {Math.round(episode.estimated_duration_seconds ?? 0)}s /{" "}
                {episode.target_duration_seconds}s
                {episode.project_id
                  ? ` - ${projectById.get(episode.project_id)?.name ?? "project"}`
                  : ""}
              </small>
            </button>
          ))}
        </div>
      ) : !props.isLoading ? (
        <div className="emptyState compact">
          Create an episode to begin production.
        </div>
      ) : null}
    </section>
  );
}

function ApprovalQueuePanel(props: {
  episodes: EpisodeSummary[];
  selectedEpisodeId: string | null;
  onSelect: (episodeId: string, approval: Approval) => void;
  onApprove: (episodeId: string, approval: Approval) => void;
  onReject: (episodeId: string, approval: Approval) => void;
  actionPending: boolean;
}) {
  const episodesWithApprovals = props.episodes.filter(
    (episode) =>
      episode.pending_approval_count > 0 &&
      !["COMPLETED", "CANCELLED"].includes(episode.status),
  );
  return (
    <section className="auditPanel">
      <div className="sectionTitle">
        <h2>Pending Approvals</h2>
        <span>{episodesWithApprovals.length} episodes</span>
      </div>
      {episodesWithApprovals.map((episode) => {
        const pending = episode.pending_approvals;
        return (
          <article className="episodeRow" key={episode.id}>
            <div>
              <button
                className="linkButton"
                onClick={() => {
                  const approval = pending[0];
                  if (approval) {
                    props.onSelect(episode.id, approval);
                  }
                }}
                type="button"
              >
                <h3>{episode.title}</h3>
              </button>
              <p>
                {pending
                  .map((approval) => approvalStageLabel(approval.stage))
                  .join(", ")}{" "}
                · {episode.status}
              </p>
              <small>
                {approvalWorkflowHandoffSummary(pending[0]?.stage ?? "")}
              </small>
              <div className="inlineActions">
                {pending.map((approval) => (
                  <React.Fragment key={approval.id}>
                    <button
                      className="secondaryButton compact"
                      disabled={props.actionPending}
                      onClick={() => props.onSelect(episode.id, approval)}
                      type="button"
                    >
                      <FileText size={16} />
                      Review
                    </button>
                    <button
                      className="secondaryButton compact"
                      disabled={props.actionPending}
                      onClick={() => props.onApprove(episode.id, approval)}
                      type="button"
                    >
                      <CheckCircle2 size={16} />
                      {approvalActionLabel(approval.stage)}
                    </button>
                    <button
                      className="secondaryButton compact danger"
                      disabled={props.actionPending}
                      onClick={() => props.onReject(episode.id, approval)}
                      type="button"
                    >
                      <Ban size={16} />
                      {rejectionActionLabel(approval.stage)}
                    </button>
                  </React.Fragment>
                ))}
              </div>
            </div>
            <span
              className={`statusPill ${props.selectedEpisodeId === episode.id ? "selected" : ""}`}
            >
              {pending.length} pending
            </span>
          </article>
        );
      })}
      {episodesWithApprovals.length === 0 ? (
        <div className="emptyState">No pending approval decisions.</div>
      ) : null}
    </section>
  );
}

