function canCreateFromEditor(editor: EpisodeEditorState): boolean {
  const selectedPanelists = editor.panelistIds.filter(Boolean);
  const outputLanguages = parseOutputLanguages(editor.outputLanguages);
  return (
    editor.title.trim().length >= 3 &&
    editor.centralQuestion.trim().length >= 8 &&
    Number.isFinite(editor.targetDurationMinutes) &&
    editor.targetDurationMinutes >= 1 &&
    Number.isFinite(editor.maximumMonologueSeconds) &&
    editor.maximumMonologueSeconds >= 10 &&
    Number.isFinite(editor.postPrimerBridgeTargetDurationSeconds) &&
    editor.postPrimerBridgeTargetDurationSeconds >= 25 &&
    editor.postPrimerBridgeTargetDurationSeconds <= 45 &&
    Number.isFinite(editor.permittedDeviationPercent) &&
    editor.permittedDeviationPercent >= 0 &&
    editor.permittedDeviationPercent <= 50 &&
    Number.isFinite(editor.semanticFidelityThreshold) &&
    editor.semanticFidelityThreshold >= 0 &&
    editor.semanticFidelityThreshold <= 1 &&
    Number.isFinite(editor.mediaWidth) &&
    editor.mediaWidth >= 320 &&
    Number.isFinite(editor.mediaHeight) &&
    editor.mediaHeight >= 240 &&
    Number.isFinite(editor.mediaFps) &&
    editor.mediaFps >= 1 &&
    editor.mediaFps <= 120 &&
    Number.isFinite(editor.maximumStageRetries) &&
    editor.maximumStageRetries >= 0 &&
    editor.maximumStageRetries <= 10 &&
    Number.isFinite(editor.blockOnSyncErrorMs) &&
    editor.blockOnSyncErrorMs >= 0 &&
    outputLanguages.length > 0 &&
    editor.hostId.length > 0 &&
    selectedPanelists.length >= 3 &&
    new Set(selectedPanelists).size === selectedPanelists.length &&
    !selectedPanelists.includes(editor.hostId)
  );
}

function episodeDefinitionIsEditable(episode: Episode): boolean {
  return (
    episode.status === "DRAFT" &&
    episode.discussion_session === null &&
    episode.transcripts.length === 0 &&
    episode.assets.length === 0 &&
    episode.quality_results.length === 0 &&
    episode.approvals.length === 0 &&
    episode.publish_jobs.length === 0
  );
}

function buildEpisodeCreatePayloadFromEditor(
  editor: EpisodeEditorState,
): Record<string, unknown> {
  return {
    project_id: editor.projectId.trim() || null,
    definition: buildDefinitionFromEditor(editor),
  };
}

function realPilotEditorFromEditor(
  editor: EpisodeEditorState,
): EpisodeEditorState {
  return {
    ...editor,
    title: "Frontier KI Pilot: Wer liefert den besten praktischen Nutzen?",
    centralQuestion:
      "Welches Frontier-KI-Modell liefert heute den besten praktischen Nutzen fuer anspruchsvolle Wissensarbeit?",
    hostControl: "high",
    maximumMonologueSeconds: Math.min(
      Math.max(editor.maximumMonologueSeconds, 10),
      45,
    ),
    requiredDimensions:
      "staerken, schwaechen, kosten_nutzen, einsatzempfehlung",
    outputLanguages: editor.outputLanguages.trim() || "de",
    researchSourceTitle: "",
    researchSourceUri: "",
    researchSourceContent: "",
    requireSourceLinks: false,
    researchApprovalRequired: false,
    generateBroll: false,
    generateCitationCards: false,
    workflowMode: "transcript_review",
    retryFailedAssets: true,
    hostId: "claude",
    panelistIds: ["chatgpt", "deepseek", "grok", "gemini", "mistral"],
    panelistRoles: ["panelist", "panelist", "panelist", "panelist", "panelist"],
  };
}

function evidencePilotEditorFromEditor(
  editor: EpisodeEditorState,
): EpisodeEditorState {
  return {
    ...realPilotEditorFromEditor(editor),
    researchSourceTitle: "Frontier model pilot evidence brief",
    researchSourceUri:
      "dialecticore://operator/frontier-model-pilot-evidence-brief",
    researchSourceType: "manual_source",
    researchSourceContent: [
      "This operator brief is the allowed source material for the frontier-model pilot.",
      "The episode should compare practical usefulness for demanding knowledge work.",
      "Discuss strengths, weaknesses, cost-benefit tradeoffs, reliability, and deployment fit.",
      "ChatGPT should represent a broad OpenAI-style generalist with strong product integration.",
      "Claude should represent careful synthesis, moderation, and risk-aware reasoning.",
      "DeepSeek should represent cost-effective technical analysis and implementation focus.",
      "Grok should represent fast contrarian challenge and direct rebuttal.",
      "Gemini should represent efficient multimodal and product-suite synthesis.",
      "Mistral should represent concise European and open-model pragmatism.",
      "Treat numeric benchmark, price, market-share, and release-status statements as unsupported unless a separate approved source is added.",
      "Opinion and editorial judgment are allowed when clearly not presented as sourced facts.",
    ].join("\n"),
    requireSourceLinks: true,
    researchApprovalRequired: true,
    generateCitationCards: true,
    blockOnUnsupportedHighImpactClaims: true,
  };
}

function durationBoundsAreValid(bounds: DurationBoundsDraft): boolean {
  return (
    Number.isFinite(bounds.minimum) &&
    Number.isFinite(bounds.target) &&
    Number.isFinite(bounds.maximum) &&
    bounds.minimum >= 1 &&
    bounds.target >= 1 &&
    bounds.maximum >= 1 &&
    bounds.minimum <= bounds.target &&
    bounds.target <= bounds.maximum
  );
}

function buildDefinitionFromEditor(editor: EpisodeEditorState) {
  const dimensions = editor.requiredDimensions
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
  const outputLanguages = parseOutputLanguages(editor.outputLanguages);
  const hasResearchSource = Boolean(
    editor.researchSourceContent.trim() || editor.researchSourceUri.trim(),
  );
  return {
    ...exampleDefinition,
    title: editor.title.trim(),
    topic: {
      ...exampleDefinition.topic,
      central_question: editor.centralQuestion.trim(),
      required_dimensions:
        dimensions.length > 0
          ? dimensions
          : ["main_arguments", "risks", "next_steps"],
    },
    format: {
      ...exampleDefinition.format,
      target_duration_minutes: editor.targetDurationMinutes,
      permitted_deviation_percent: editor.permittedDeviationPercent,
      host_control: editor.hostControl,
      allow_interruptions: editor.allowInterruptions,
      allow_follow_up_questions: editor.allowFollowUpQuestions,
      maximum_monologue_seconds: editor.maximumMonologueSeconds,
      discussion_intensity: editor.discussionIntensity,
      participant_count: 1 + editor.panelistIds.length,
    },
    languages: {
      ...exampleDefinition.languages,
      source_language: outputLanguages[0] ?? "en",
      outputs: outputLanguages.map((language, index) => ({
        language,
        mode: index === 0 ? "canonical" : "localized_reperformance",
      })),
      semantic_fidelity_threshold: editor.semanticFidelityThreshold,
      allow_new_claims: editor.allowNewClaims,
    },
    research: {
      ...exampleDefinition.research,
      enabled:
        hasResearchSource ||
        editor.requireSourceLinks ||
        editor.researchApprovalRequired,
      depth: editor.researchDepth,
      require_source_links: editor.requireSourceLinks || hasResearchSource,
      approval_required: editor.researchApprovalRequired || hasResearchSource,
    },
    media: {
      ...exampleDefinition.media,
      aspect_ratio: reducedAspectRatio(editor.mediaWidth, editor.mediaHeight),
      width: editor.mediaWidth,
      height: editor.mediaHeight,
      fps: editor.mediaFps,
      visual_style: editor.visualStyle.trim() || "studio_realistic",
      camera_style: editor.cameraStyle.trim() || "multi_camera",
      scene_reference_image_uri: editor.sceneReferenceImageUri.trim() || null,
      subtitle_mode: editor.subtitleMode,
      generate_broll: editor.generateBroll,
      generate_citation_cards: editor.generateCitationCards,
      evidence_presentation: "review_only",
      opening: {
        enabled: editor.openingEnabled,
        narration_brief: editor.openingNarrationBrief.trim(),
        source_references: editor.openingSourceReferences
          .split(",")
          .map((item) => item.trim())
          .filter(Boolean),
        introduce_participants: editor.openingIntroduceParticipants,
        post_primer_bridge: {
          editorial_brief: editor.postPrimerBridgeBrief.trim(),
          target_duration_seconds: editor.postPrimerBridgeTargetDurationSeconds,
          introduce_participants: editor.openingIntroduceParticipants,
        },
        narrator_profile_id: editor.primerNarratorProfileId || null,
        target_duration_seconds: editor.primerTargetDurationSeconds,
        media_discovery: {
          enabled: editor.primerMediaDiscoveryEnabled,
          model_endpoint_id: editor.primerMediaModelEndpointId.trim() || null,
          model_id: editor.primerMediaModelId.trim() || null,
          max_candidates: editor.primerMediaMaxCandidates,
          acquisition_policy: editor.primerMediaAcquisitionPolicy,
        },
        visual_planner: {
          enabled: editor.primerVisualPlannerEnabled,
          model_endpoint_id:
            editor.primerVisualPlannerModelEndpointId.trim() || null,
          model_id: editor.primerVisualPlannerModelId.trim() || null,
          automatic_draft_render: editor.primerVisualPlannerAutoRenderDraft,
          target_shot_duration_seconds:
            editor.primerVisualPlannerShotDurationSeconds,
          minimum_shot_duration_seconds: 5,
          allow_generated_connective_visuals:
            editor.primerVisualPlannerAllowGeneratedConnectiveVisuals,
          exclude_people: editor.primerVisualPlannerExcludePeople,
        },
      },
    },
    workflow: {
      ...exampleDefinition.workflow,
      mode: editor.workflowMode,
      production_target: editor.productionTarget,
      retry_failed_assets: editor.retryFailedAssets,
      maximum_stage_retries: editor.maximumStageRetries,
    },
    quality: {
      ...exampleDefinition.quality,
      block_on_unsupported_high_impact_claims:
        editor.blockOnUnsupportedHighImpactClaims,
      block_on_missing_audio: editor.blockOnMissingAudio,
      block_on_sync_error_ms: editor.blockOnSyncErrorMs,
      block_on_missing_subtitles: editor.blockOnMissingSubtitles,
    },
    participants: [
      { participant_profile_id: editor.hostId, role: "moderator" },
      ...editor.panelistIds.map((id, index) => ({
        participant_profile_id: id,
        role: editor.panelistRoles[index] ?? "panelist",
      })),
    ],
  };
}

function reducedAspectRatio(width: number, height: number): string {
  const safeWidth = Math.max(1, Math.round(width));
  const safeHeight = Math.max(1, Math.round(height));
  const divisor = greatestCommonDivisor(safeWidth, safeHeight);
  return `${safeWidth / divisor}:${safeHeight / divisor}`;
}

function greatestCommonDivisor(left: number, right: number): number {
  let a = Math.abs(left);
  let b = Math.abs(right);
  while (b !== 0) {
    const next = a % b;
    a = b;
    b = next;
  }
  return a || 1;
}

function manualResearchSourcesFromEditor(editor: EpisodeEditorState) {
  const title = editor.researchSourceTitle.trim();
  const content = editor.researchSourceContent.trim();
  if (!title || !content) {
    return [];
  }
  const uri = editor.researchSourceUri.trim();
  return [
    {
      title,
      uri: uri || null,
      source_type: editor.researchSourceType,
      content,
    },
  ];
}

function researchRetrievalTargetsFromEditor(editor: EpisodeEditorState) {
  const uri = editor.researchSourceUri.trim();
  const content = editor.researchSourceContent.trim();
  if (!uri || content) {
    return [];
  }
  const title = editor.researchSourceTitle.trim();
  return [
    {
      title: title || null,
      uri,
      source_type: editor.researchSourceType,
    },
  ];
}

function parseOutputLanguages(value: string): string[] {
  const languages = value
    .split(",")
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean);
  return Array.from(new Set(languages));
}

function useQueryClientAccess() {
  return queryClient;
}

async function invalidateProductionQueries(client: QueryClient) {
  await Promise.all([
    client.invalidateQueries({ queryKey: ["episodes"] }),
    client.invalidateQueries({ queryKey: ["episode-detail"] }),
    client.invalidateQueries({ queryKey: ["episode-media-index"] }),
    client.invalidateQueries({ queryKey: ["projects"] }),
    client.invalidateQueries({ queryKey: ["language-profiles"] }),
    client.invalidateQueries({ queryKey: ["audit-events"] }),
    client.invalidateQueries({ queryKey: ["system-health"] }),
    client.invalidateQueries({ queryKey: ["system-workers"] }),
    client.invalidateQueries({ queryKey: ["system-backups"] }),
    client.invalidateQueries({ queryKey: ["publisher-targets"] }),
    client.invalidateQueries({ queryKey: ["workflow-retry-backlog"] }),
    client.invalidateQueries({ queryKey: ["workflow-orchestration-evidence"] }),
    client.invalidateQueries({ queryKey: ["live-provider-readiness"] }),
    client.invalidateQueries({ queryKey: ["episode-pilot-readiness"] }),
    client.invalidateQueries({ queryKey: ["workflow-replay"] }),
    client.invalidateQueries({ queryKey: ["completion-readiness"] }),
    client.invalidateQueries({ queryKey: ["production-test-report"] }),
  ]);
}

async function invalidateProductionEvidenceQueries(client: QueryClient) {
  await Promise.all([
    client.invalidateQueries({ queryKey: ["live-provider-readiness"] }),
    client.invalidateQueries({ queryKey: ["episode-pilot-readiness"] }),
    client.invalidateQueries({ queryKey: ["workflow-replay"] }),
    client.invalidateQueries({ queryKey: ["completion-readiness"] }),
    client.invalidateQueries({ queryKey: ["production-test-report"] }),
  ]);
}

function pendingTranscriptApproval(episode: Episode | null): Approval | null {
  return (
    episode?.approvals.find(
      (approval) =>
        approval.stage === "transcript_review" &&
        approval.decision === "pending",
    ) ?? null
  );
}

function pendingResearchApproval(episode: Episode | null): Approval | null {
  return (
    episode?.approvals.find(
      (approval) =>
        approval.stage === "research_review" && approval.decision === "pending",
    ) ?? null
  );
}

function pendingApproval(episode: Episode | null): Approval | null {
  return (
    episode?.approvals.find(
      (approval) =>
        approval.decision === "pending" && isActionableApproval(episode, approval),
    ) ??
    null
  );
}

function isActionableApproval(episode: Episode, approval: Approval): boolean {
  if (!['preview_render_review', 'final_render_review'].includes(approval.stage)) {
    return true;
  }
  if (approval.target_type !== "render_asset" || !approval.target_id) {
    return true;
  }
  const renderAsset = episode.assets.find(
    (asset) => asset.id === approval.target_id && asset.asset_type === "render",
  );
  if (!renderAsset || renderAsset.source_entity_type !== "timeline_asset") {
    return true;
  }
  if (!isCurrentTalkshowRenderAsset(episode, renderAsset)) {
    return false;
  }
  const expectedRenderType =
    approval.stage === "preview_render_review" ? "preview" : "final";
  return latestRenderAsset(episode, expectedRenderType)?.id === renderAsset.id;
}

function pendingFinalRenderApproval(episode: Episode | null): Approval | null {
  if (!episode) {
    return null;
  }
  const renderAsset = latestRenderAsset(episode, "final");
  if (!renderAsset) {
    return null;
  }
  return (
    episode.approvals.find(
      (approval) =>
        approval.stage === "final_render_review" &&
        approval.target_type === "render_asset" &&
        approval.target_id === renderAsset.id &&
        approval.decision === "pending",
    ) ?? null
  );
}

function pendingPreviewRenderApproval(
  episode: Episode | null,
): Approval | null {
  if (!episode) {
    return null;
  }
  const renderAsset = latestRenderAsset(episode, "preview");
  if (!renderAsset) {
    return null;
  }
  return (
    episode.approvals.find(
      (approval) =>
        approval.stage === "preview_render_review" &&
        approval.target_type === "render_asset" &&
        approval.target_id === renderAsset.id &&
        approval.decision === "pending",
    ) ?? null
  );
}

function activeRenderStatus(episode: Episode | null): string | null {
  const activeRender = [...(episode?.assets ?? [])]
    .reverse()
    .find(
      (asset) =>
        asset.asset_type === "render" &&
        (asset.status === "submitted" || asset.status === "running"),
    );
  if (!activeRender) {
    return null;
  }
  const renderType = activeRender.generation_metadata?.render_type;
  const label = renderType === "final" ? "final render" : "preview render";
  return activeRender.status === "running" ? `${label} rendering` : `${label} queued`;
}

function currentTalkshowRenderAsset(
  episode: Episode | null,
  renderType: "preview" | "final",
): Asset | null {
  if (!episode) {
    return null;
  }
  const renders = episode.assets.filter(
    (asset) =>
      asset.asset_type === "render" &&
      isCurrentTalkshowRenderAsset(episode, asset) &&
      asset.generation_metadata?.render_type === renderType,
  );
  return renders.length > 0 ? renders[renders.length - 1] : null;
}

function previewRenderReviewIssue(episode: Episode | null): string | null {
  const approval = pendingPreviewRenderApproval(episode);
  if (!episode || !approval?.target_id) {
    return null;
  }
  const renderAsset = episode.assets.find((asset) => asset.id === approval.target_id);
  if (!renderAsset) {
    return "The preview artifact is unavailable and cannot be approved.";
  }
  if (renderAsset.generation_metadata?.review_scope !== "full_timeline") {
    return "This legacy preview contains only part of the episode and omits the completed primer. Return it to the timeline, then rebuild the full episode timeline before rendering a new preview.";
  }
  const timelineAsset = episode.assets.find(
    (asset) => asset.id === renderAsset.source_entity_id && asset.asset_type === "timeline",
  );
  const timeline = timelineAsset?.generation_metadata?.timeline_json;
  const expectedDurationMs =
    timeline &&
    typeof timeline === "object" &&
    typeof (timeline as Record<string, unknown>).duration_ms === "number"
      ? (timeline as Record<string, number>).duration_ms
      : 0;
  const actualDurationMs = Number(renderAsset.duration_ms ?? 0);
  if (expectedDurationMs > 0 && actualDurationMs + 2_000 < expectedDurationMs) {
    return "This preview does not cover the full episode timeline. Return it to the timeline, then rebuild and render a complete preview.";
  }
  return null;
}

function requiresFullTimelineRebuild(episode: Episode | null): boolean {
  if (!episode) {
    return false;
  }
  return episode.assets.some(
    (asset) =>
      asset.asset_type === "render" &&
      asset.status === "rejected" &&
      asset.generation_metadata?.render_type === "preview" &&
      asset.generation_metadata?.review_scope !== "full_timeline" &&
      isCurrentTalkshowRenderAsset(episode, asset),
  );
}

function finalRenderApproved(episode: Episode, renderAsset: Asset): boolean {
  if (renderAsset.generation_metadata?.approval_status === "approved") {
    return true;
  }
  return episode.approvals.some(
    (approval) =>
      approval.stage === "final_render_review" &&
      approval.target_type === "render_asset" &&
      approval.target_id === renderAsset.id &&
      approval.decision === "approved",
  );
}

function canStartProduction(episode: Episode | null): boolean {
  if (!episode || pendingResearchApproval(episode)) {
    return false;
  }
  if (workflowPaused(episode) || workflowCancelled(episode)) {
    return false;
  }
  if (hasRunningWorkflowRun(episode)) {
    return false;
  }
  if (["COMPLETED", "CANCELLED"].includes(episode.status)) {
    return false;
  }
  if (
    episode.definition.research?.enabled &&
    latestEvidencePackAsset(episode) === null
  ) {
    return false;
  }
  return true;
}

function canRunWorkflowUntilBlocked(episode: Episode | null): boolean {
  if (!episode || pendingApproval(episode)) {
    return false;
  }
  if (workflowPaused(episode) || workflowCancelled(episode)) {
    return false;
  }
  if (["COMPLETED", "CANCELLED", "FAILED"].includes(episode.status)) {
    return false;
  }
  return hasRunningWorkflowRun(episode) || canStartProduction(episode);
}

function canAdvanceWorkflow(episode: Episode | null): boolean {
  return Boolean(
    episode &&
    hasRunningWorkflowRun(episode) &&
    !workflowPaused(episode) &&
    !workflowCancelled(episode) &&
    !["COMPLETED", "CANCELLED"].includes(episode.status),
  );
}

function canPauseWorkflow(episode: Episode | null): boolean {
  return Boolean(
    episode &&
    !workflowPaused(episode) &&
    !["COMPLETED", "CANCELLED"].includes(episode.status),
  );
}

function canResumeWorkflow(episode: Episode | null): boolean {
  return Boolean(
    episode && workflowPaused(episode) && episode.status !== "CANCELLED",
  );
}

function canCancelWorkflow(episode: Episode | null): boolean {
  return Boolean(
    episode && !["COMPLETED", "CANCELLED"].includes(episode.status),
  );
}

function canRetryWorkflow(episode: Episode | null): boolean {
  return Boolean(
    episode &&
    (episode.status === "FAILED" ||
      episode.assets.some((asset) => asset.status === "failed")),
  );
}

function canContinueAfterManualEdit(episode: Episode | null): boolean {
  return Boolean(
    episode &&
    !["COMPLETED", "CANCELLED"].includes(episode.status) &&
    (workflowPaused(episode) ||
      episode.status === "FAILED" ||
      episode.workflow_control?.last_rejected_stage),
  );
}

function canApproveWorkflowStage(episode: Episode | null): boolean {
  return Boolean(
    episode &&
    !workflowPaused(episode) &&
    !["COMPLETED", "CANCELLED", "FAILED"].includes(episode.status),
  );
}

function canCompleteWorkflow(
  episode: Episode | null,
  completionReadiness: CompletionReadiness | null,
): boolean {
  return Boolean(
    episode &&
    completionReadiness?.status === "pass" &&
    !workflowPaused(episode) &&
    !["COMPLETED", "CANCELLED", "FAILED"].includes(episode.status),
  );
}

function canRejectWorkflowStage(episode: Episode | null): boolean {
  return Boolean(
    episode &&
    !workflowPaused(episode) &&
    !["COMPLETED", "CANCELLED", "FAILED"].includes(episode.status),
  );
}

function workflowPaused(episode: Episode): boolean {
  return episode.workflow_control?.paused === true;
}

function workflowCancelled(episode: Episode): boolean {
  return (
    episode.status === "CANCELLED" ||
    episode.workflow_control?.cancelled === true
  );
}

function workflowRun(episode: Episode | null): WorkflowRun | null {
  const run = episode?.workflow_control?.run;
  if (!run || typeof run !== "object" || Array.isArray(run)) {
    return null;
  }
  return run as WorkflowRun;
}

function hasRunningWorkflowRun(episode: Episode | null): boolean {
  return workflowRun(episode)?.state === "running";
}

function workflowRunSummary(episode: Episode | null): string | null {
  const run = workflowRun(episode);
  if (!run) {
    return null;
  }
  const stagePlan = Array.isArray(run.stage_plan) ? run.stage_plan : [];
  const completedStages = stagePlan.filter(
    (stage) => stage.status === "completed",
  ).length;
  const currentStage = run.current_stage ?? episode?.status ?? "UNKNOWN";
  const signalCount = Array.isArray(run.signals) ? run.signals.length : 0;
  const temporalLog = episode?.workflow_control?.temporal_signal_log;
  const temporalCount = Array.isArray(temporalLog)
    ? (temporalLog as TemporalSignalAttempt[]).length
    : 0;
  const workflowEventLog = episode?.workflow_control?.workflow_event_log;
  const eventCount = Array.isArray(workflowEventLog)
    ? (workflowEventLog as WorkflowEvent[]).length
    : 0;
  const runLabel = run.run_sequence ? `Run ${run.run_sequence}` : "Run";
  const state = run.state ?? "running";
  return `${runLabel} ${state} · ${currentStage} · ${completedStages}/${stagePlan.length} stages · ${signalCount} signals · ${temporalCount} temporal · ${eventCount} replay`;
}

function workflowTemporalSignalLog(
  episode: Episode | null,
): TemporalSignalAttempt[] {
  const temporalLog = episode?.workflow_control?.temporal_signal_log;
  return Array.isArray(temporalLog)
    ? (temporalLog as TemporalSignalAttempt[])
    : [];
}

function workflowTemporalStageDispatchLog(
  episode: Episode | null,
): TemporalStageDispatch[] {
  const dispatchLog = episode?.workflow_control?.temporal_stage_dispatch_log;
  return Array.isArray(dispatchLog)
    ? (dispatchLog as TemporalStageDispatch[])
    : [];
}

function workflowWorkerPasses(episode: Episode | null): WorkflowWorkerPass[] {
  const attempts = episode?.workflow_control?.worker_orchestration_log;
  return Array.isArray(attempts) ? (attempts as WorkflowWorkerPass[]) : [];
}

function latestTalkshowProductionHandoff(
  latestAdvance: WorkflowAdvanceResult | null,
  episode: Episode | null,
): TalkshowProductionHandoff | null {
  if (!episode) {
    return null;
  }
  const persistedHandoff = latestPersistedTalkshowProductionHandoff(episode);
  if (persistedHandoff) {
    return persistedHandoff;
  }
  if (!latestAdvance || latestAdvance.episode.id !== episode.id) {
    return null;
  }
  const rawHandoffs = latestAdvance.summary.production_handoffs;
  if (!Array.isArray(rawHandoffs)) {
    return null;
  }
  const handoff = rawHandoffs.find(
    (item) =>
      typeof item === "object" &&
      item !== null &&
      !Array.isArray(item) &&
      (item as Record<string, unknown>).episode_id === episode.id,
  );
  return handoff ? (handoff as TalkshowProductionHandoff) : null;
}

function latestPersistedTalkshowProductionHandoff(
  episode: Episode,
): TalkshowProductionHandoff | null {
  const workerPasses = workflowWorkerPasses(episode);
  for (const workerPass of workerPasses.slice().reverse()) {
    const handoff = workerPass.production_handoff;
    if (handoff?.schema_version === "talkshow_production_handoff.v1") {
      return handoff;
    }
  }
  const lastWorkerOrchestration =
    workflowRun(episode)?.last_worker_orchestration;
  if (
    lastWorkerOrchestration &&
    typeof lastWorkerOrchestration === "object" &&
    !Array.isArray(lastWorkerOrchestration)
  ) {
    const handoff = (lastWorkerOrchestration as Record<string, unknown>)
      .production_handoff;
    if (
      handoff &&
      typeof handoff === "object" &&
      !Array.isArray(handoff) &&
      (handoff as Record<string, unknown>).schema_version ===
        "talkshow_production_handoff.v1"
    ) {
      return handoff as TalkshowProductionHandoff;
    }
  }
  return null;
}

function latestPersistedRunUntilBlockedEvidence(
  episode: Episode | null,
): WorkflowRunUntilBlockedEvidenceLike | null {
  const controlEvidence = episode?.workflow_control?.last_run_until_blocked;
  if (
    controlEvidence &&
    typeof controlEvidence === "object" &&
    !Array.isArray(controlEvidence)
  ) {
    return controlEvidence as WorkflowRunUntilBlockedEvidenceLike;
  }
  const runEvidence = workflowRun(episode)?.last_run_until_blocked;
  if (
    runEvidence &&
    typeof runEvidence === "object" &&
    !Array.isArray(runEvidence)
  ) {
    return runEvidence as WorkflowRunUntilBlockedEvidenceLike;
  }
  return null;
}

function productionHandoffStatusClass(
  status?: string,
): "pass" | "warning" | "fail" {
  if (
    status === "delivery_ready" ||
    status === "review_ready" ||
    status === "media_ready"
  ) {
    return "pass";
  }
  if (status === "blocked") {
    return "fail";
  }
  return "warning";
}

function readyLabel(ready?: boolean): string {
  return ready ? "ready" : "missing";
}

function localizedOutputsSummary(handoff: TalkshowProductionHandoff): string {
  const localized = handoff.localized_outputs;
  if (!localized?.required) {
    return "not configured";
  }
  const approved = localized.approved_language_count ?? 0;
  const required = localized.required_language_count ?? 0;
  const blockers = [
    ...(localized.missing_languages ?? []),
    ...(localized.not_approved_languages ?? []),
    ...(localized.qc_missing_languages ?? []),
    ...(localized.qc_failing_languages ?? []),
  ];
  const status = localized.ready ? "ready" : "pending";
  const suffix =
    blockers.length > 0 ? ` · ${blockers.slice(0, 3).join(", ")}` : "";
  return `${status} · ${approved}/${required} approved${suffix}`;
}

function productionHandoffRenderSummary(
  handoff: TalkshowProductionHandoff,
): string {
  const render = handoff.render ?? {};
  if (render.final_render_qc_status === "fail") {
    return "final QC failed";
  }
  if (render.preview_render_qc_status === "fail") {
    return "preview QC failed";
  }
  if (render.delivery_package_qc_status === "fail") {
    return "package QC failed";
  }
  if (
    render.production_manifest_asset_id &&
    render.production_manifest_valid === false
  ) {
    return "manifest invalid";
  }
  if (
    render.production_manifest_asset_id &&
    render.production_manifest_publish_evidence_valid === false
  ) {
    return "manifest stale";
  }
  if (
    render.production_manifest_asset_id &&
    render.final_render_approved &&
    render.delivery_package_qc_status === "pass" &&
    render.production_manifest_valid &&
    handoff.publish?.ready
  ) {
    return handoff.publish?.publish_job_dry_run
      ? "dry run complete"
      : "published";
  }
  if (
    render.production_manifest_asset_id &&
    render.final_render_approved &&
    render.delivery_package_qc_status === "pass" &&
    render.production_manifest_valid
  ) {
    return "publish pending";
  }
  if (render.delivery_package_asset_id && !render.delivery_package_qc_status) {
    return "package QC pending";
  }
  if (render.delivery_package_asset_id) {
    return "package ready";
  }
  if (render.final_render_asset_id && !render.final_render_approved) {
    return "final approval pending";
  }
  if (render.final_render_asset_id) {
    return "final approved";
  }
  if (render.preview_render_asset_id && !render.preview_render_approved) {
    return "preview approval pending";
  }
  if (render.preview_render_asset_id) {
    return "preview approved";
  }
  return "not rendered";
}

function workflowStageAttemptSummary(attempt: WorkflowStageAttempt): string {
  const details = [
    `${attempt.progress_count ?? 0} progressed`,
    `${attempt.error_count ?? 0} errors`,
    `${attempt.episodes_scanned ?? 0} scanned`,
    `${attempt.skipped ?? 0} skipped`,
  ];
  if ((attempt.workflow_blocked ?? 0) > 0) {
    details.push(`${attempt.workflow_blocked} workflow-blocked`);
  }
  if ((attempt.targeted_audio_assets ?? 0) > 0) {
    details.push(`${attempt.targeted_audio_assets} audio targeted`);
  }
  if ((attempt.repair_audio_assets ?? 0) > 0) {
    details.push(`${attempt.repair_audio_assets} audio repairs`);
  }
  if ((attempt.targeted_visual_assets ?? 0) > 0) {
    details.push(`${attempt.targeted_visual_assets} visuals targeted`);
  }
  if ((attempt.repair_visual_assets ?? 0) > 0) {
    details.push(`${attempt.repair_visual_assets} visual repairs`);
  }
  return details.join(" · ");
}

function safeWorkflowRunStartError(error: unknown): string {
  if (!error || typeof error !== "object" || Array.isArray(error)) {
    return "workflow run could not be started";
  }
  const record = error as Record<string, unknown>;
  const episode =
    typeof record.episode_id === "string"
      ? record.episode_id.slice(0, 8)
      : null;
  const reason =
    typeof record.error === "string" ? record.error : "unknown error";
  return episode ? `${episode} · ${reason}` : reason;
}

function workflowEventLog(episode: Episode | null): WorkflowEvent[] {
  const events = episode?.workflow_control?.workflow_event_log;
  return Array.isArray(events) ? (events as WorkflowEvent[]) : [];
}

function formatWorkflowEvidenceTime(value?: string | null): string {
  if (!value) {
    return "unknown time";
  }
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleString();
}

function liveQueueTotal(queues: Record<string, number>): number {
  return Object.values(queues).reduce(
    (total, value) => total + Number(value || 0),
    0,
  );
}

function liveQueueSummary(queues: Record<string, number>): string {
  const ordered = [
    ["pending_audio_jobs", "audio"],
    ["pending_visual_jobs", "visual"],
    ["pending_subtitle_jobs", "subtitles"],
    ["failed_assets", "failed"],
    ["completed_renders", "renders"],
  ] as const;
  const entries = ordered
    .map(([name, label]) => [label, Number(queues[name] || 0)] as const)
    .filter(([, value]) => value > 0)
    .map(([label, value]) => `${label}: ${value}`);
  return entries.length > 0 ? entries.join(" · ") : "no queued work";
}

function redisFanoutSummary(fanout?: LiveStatusEvent["redis_fanout"]): string {
  if (!fanout) {
    return "waiting for first event";
  }
  if (fanout.status === "published") {
    return `${fanout.delivered_count ?? 0} delivered · ${fanout.channel ?? "channel unknown"}`;
  }
  if (fanout.status === "disabled") {
    return `disabled · ${fanout.channel ?? "channel unknown"}`;
  }
  if (fanout.error) {
    return fanout.error;
  }
  if (fanout.reason) {
    return fanout.reason;
  }
  return fanout.channel ?? "channel unknown";
}

function workflowReplayIssueSummary(issue: WorkflowReplayIssue): string {
  if (issue.field) {
    return `${issue.field}: ${String(issue.replayed)} replayed, ${String(issue.current)} stored`;
  }
  if (issue.expected_sequence || issue.actual_sequence) {
    return `sequence ${issue.actual_sequence ?? "unknown"}, expected ${issue.expected_sequence ?? "unknown"}`;
  }
  return "Check workflow_control.workflow_event_log against workflow_control.run.";
}

function workflowEventStage(event: WorkflowEvent): string {
  return (
    event.stage ??
    event.source ??
    `sequence ${event.event_sequence ?? "unknown"}`
  );
}

function workflowEventRecordedAt(event: WorkflowEvent): string | undefined {
  return event.recorded_at;
}

function completionAssetLabel(value?: string | null): string {
  if (!value) {
    return "missing";
  }
  return value.length > 12 ? value.slice(0, 8) : value;
}

function productionTestAssetSummary(
  asset?: ProductionTestAssetEvidence | null,
): string {
  if (!asset?.asset_id) {
    return "missing";
  }
  const status = asset.status ?? "unknown";
  const checksum = asset.checksum ? "checksum" : "no checksum";
  const storage = asset.downloadable
    ? `downloadable${asset.file_size_bytes ? ` ${formatBytes(asset.file_size_bytes)}` : ""}`
    : (asset.download_missing_reason ??
      (asset.storage_uri ? "stored object missing" : "no storage"));
  return `${completionAssetLabel(asset.asset_id)} · ${status} · ${storage} · ${checksum}`;
}

function productionTestAssetLink(
  asset?: ProductionTestAssetEvidence | null,
): React.ReactNode {
  const summary = productionTestAssetSummary(asset);
  if (!asset?.download_url) {
    return summary;
  }
  return (
    <a href={`${apiBaseUrl}${asset.download_url}`} rel="noreferrer">
      {summary}
    </a>
  );
}

function ProductionReportDownloadButton(props: {
  asset?: ProductionTestAssetEvidence | null;
  label: string;
}) {
  if (!props.asset?.download_url || !props.asset.downloadable) {
    return null;
  }
  return (
    <a
      className="secondaryButton compact"
      href={`${apiBaseUrl}${props.asset.download_url}`}
      rel="noreferrer"
    >
      <Download size={16} />
      {props.label}
    </a>
  );
}

function productionTestPublishSummary(report: ProductionTestReport): string {
  const job = report.publish;
  if (!job?.publish_job_id) {
    return "missing";
  }
  return `${completionAssetLabel(job.publish_job_id)} · ${job.status ?? "unknown"} · ${
    job.dry_run ? "dry run" : "live"
  }`;
}

function productionPublishEvidenceBindingSummary(
  report: ProductionTestReport,
): string {
  const binding = report.publish_evidence_binding;
  if (!binding) {
    return "not checked";
  }
  if (binding.status === "missing") {
    return "publish job missing";
  }
  return [
    binding.status ?? "unknown",
    binding.dry_run ? "dry-run" : "live",
    binding.payload_package_matches ? "package bound" : "package mismatch",
    binding.current_manifest_embeds_publish_job
      ? "manifest embeds publish"
      : "manifest missing publish",
    binding.current_manifest_publish_job_status_matches
      ? "publish status matches"
      : "publish status mismatch",
    binding.payload_manifest_is_current
      ? "payload manifest current"
      : "payload manifest refreshed",
    binding.payload_production_manifest_schema_version
      ? `payload ${binding.payload_production_manifest_schema_version}`
      : "",
  ]
    .filter(Boolean)
    .join(" · ");
}

function productionTestPackageInspectionSummary(
  report: ProductionTestReport,
): string {
  const inspection = report.package_inspection;
  if (!inspection) {
    return "missing";
  }
  const issueSuffix =
    (inspection.issues?.length ?? 0) > 0
      ? ` · ${inspection.issues?.slice(0, 2).join(", ")}`
      : "";
  return `${inspection.status ?? "unknown"} · ${inspection.file_count ?? 0} files · ${
    inspection.manifest_schema_version ?? "no manifest"
  }${issueSuffix}`;
}

function productionAcceptanceSummary(report: ProductionTestReport): string {
  const summary = report.acceptance_summary;
  if (!summary) {
    return "not summarized";
  }
  const target = pilotProductionTargetLabel(
    summary.production_target ?? undefined,
  );
  const result = summary.status ?? "unknown";
  return `${result} · ${target} · ${summary.production_target_satisfied ? "target satisfied" : "target blocked"}`;
}

function productionRealLifeTestReadinessSummary(
  report: ProductionTestReport,
): string {
  const readiness = report.real_life_test_readiness;
  if (!readiness) {
    return "not checked";
  }
  const recommended = readiness.recommended_mode
    ? `mode ${pilotProductionTargetLabel(readiness.recommended_mode)}`
    : "";
  const audioBlockers = readiness.audio_first_blockers?.length
    ? `audio blockers ${readiness.audio_first_blockers.length}`
    : "";
  const visualBlockers = readiness.native_visual_blockers?.length
    ? `visual blockers ${readiness.native_visual_blockers.length}`
    : "";
  return [
    readiness.ready ? "ready" : "blocked",
    `audio-first ${realLifeReadyLabel(readiness.audio_first_ready)}`,
    `native visual ${realLifeReadyLabel(readiness.native_visual_ready)}`,
    readiness.live_provider_preflight_ready
      ? "live providers ready"
      : "live providers blocked",
    readiness.managed_media_smoke_ready
      ? "B1 media smoke ready"
      : "B1 media smoke blocked",
    recommended,
    audioBlockers,
    visualBlockers,
    productionTestNextAction(readiness.next_action),
  ]
    .filter(Boolean)
    .join(" · ");
}

function realLifeReadyLabel(ready?: boolean): string {
  return ready ? "ready" : "blocked";
}

function productionTestMediaReadinessSummary(
  report: ProductionTestReport,
): string {
  const media = report.media_readiness;
  if (!media) {
    return "not checked";
  }
  const managedEndpoints = media.managed_media_required_endpoints ?? [];
  const requiredPresets = Array.from(
    new Set(
      managedEndpoints.flatMap((endpoint) =>
        Array.isArray(endpoint.required_presets)
          ? endpoint.required_presets
          : [],
      ),
    ),
  );
  const missingCount = (media.managed_media_missing_preset_endpoints ?? [])
    .length;
  const audioExecution = media.audio_generation;
  const audioExecutionStatus = audioExecution?.status
    ? `speech ${audioExecution.status}`
    : `speech ${readyLabel(media.audio_generation_ready ?? undefined)}`;
  const audioExecutionCounts =
    audioExecution && (audioExecution.voicebox_asset_count ?? 0) > 0
      ? `${audioExecution.completed_artifact_count ?? 0}/${audioExecution.voicebox_asset_count ?? 0} speech` +
        ((audioExecution.failed_count ?? 0) > 0
          ? `, ${audioExecution.failed_count} failed`
          : "") +
        ((audioExecution.cancelled_count ?? 0) > 0
          ? `, ${audioExecution.cancelled_count} cancelled`
          : "") +
        ((audioExecution.blocked_cancelled_count ?? 0) > 0
          ? `, ${audioExecution.blocked_cancelled_count} reset needed`
          : "") +
        ((audioExecution.submitted_or_running_count ?? 0) > 0
          ? `, ${audioExecution.submitted_or_running_count} running`
          : "")
      : "";
  const audioProvider =
    audioExecution?.provider_ready === false
      ? `provider blocked (${audioExecution.unhealthy_endpoint_count ?? 0} unhealthy, ${
          audioExecution.unknown_health_endpoint_count ?? 0
        } unknown)`
      : audioExecution?.provider_ready === true
        ? "provider ready"
        : "";
  const execution = media.managed_media_execution;
  const executionStatus = execution?.status
    ? `execution ${execution.status}`
    : `execution ${readyLabel(media.managed_media_execution_ready ?? undefined)}`;
  const executionAction = managedMediaOperatorActionLabel(
    media.managed_media_operator_action,
  );
  const smoke = media.managed_media_smoke;
  const smokeSummary = smoke?.status
    ? `smoke ${smoke.status}` +
      (smoke.failure_category ? ` (${smoke.failure_category})` : "")
    : "";
  const executionCounts =
    execution && (execution.managed_asset_count ?? 0) > 0
      ? `${execution.completed_artifact_count ?? 0}/${execution.managed_asset_count ?? 0} artifacts` +
        ((execution.failed_count ?? 0) > 0
          ? `, ${execution.failed_count} failed`
          : "") +
        ((execution.submitted_or_running_count ?? 0) > 0
          ? `, ${execution.submitted_or_running_count} running`
          : "")
      : "";
  return [
    `audio ${readyLabel(media.audio_first_ready)}`,
    audioExecutionStatus,
    audioExecutionCounts,
    audioProvider,
    audioOperatorActionLabel(media.audio_operator_action),
    `visual ${readyLabel(media.native_visual_ready)}`,
    `config ${readyLabel(media.native_visual_config_ready)}`,
    `prompt ${readyLabel(media.native_prompt_admission_ready)}`,
    `catalog ${readyLabel(media.managed_media_catalog_ready)}`,
    executionStatus,
    executionCounts,
    smokeSummary,
    executionAction,
    requiredPresets.length
      ? `presets ${requiredPresets.join(", ")}`
      : "no remote presets",
    missingCount ? `${missingCount} missing preset groups` : "",
  ]
    .filter(Boolean)
    .join(" · ");
}

function productionTestVisualSourceSummary(
  report: ProductionTestReport,
): string {
  const summary =
    report.media_readiness?.visual_source_summary ??
    report.completion?.visual_source_summary;
  return completionVisualSourceSummary(summary);
}

function productionTestSpeechGenerationSummary(
  report: ProductionTestReport,
): string {
  const audio = report.media_readiness?.audio_generation;
  if (!audio) {
    return "not checked";
  }
  const provider =
    audio.provider_ready === false
      ? `provider blocked (${audio.unhealthy_endpoint_count ?? 0} unhealthy, ${
          audio.unknown_health_endpoint_count ?? 0
        } unknown)`
      : audio.provider_ready === true
        ? "provider ready"
        : "provider unknown";
  return [
    audio.status ?? "unknown",
    `${audio.completed_artifact_count ?? 0}/${audio.voicebox_asset_count ?? 0} complete`,
    (audio.failed_count ?? 0) > 0 ? `${audio.failed_count} failed` : "",
    (audio.cancelled_count ?? 0) > 0
      ? `${audio.cancelled_count} cancelled`
      : "",
    (audio.submitted_or_running_count ?? 0) > 0
      ? `${audio.submitted_or_running_count} running`
      : "",
    provider,
    audioOperatorActionLabel(report.media_readiness?.audio_operator_action),
  ]
    .filter(Boolean)
    .join(" · ");
}

function productionManagedMediaExecutionSummary(
  report: ProductionTestReport,
): string {
  const execution = report.media_readiness?.managed_media_execution;
  if (!execution) {
    return "not checked";
  }
  const models = execution.models?.length
    ? `models ${execution.models.join(", ")}`
    : "";
  const operations = execution.operations?.length
    ? `ops ${execution.operations.join(", ")}`
    : "";
  return [
    execution.status ?? "unknown",
    `${execution.completed_artifact_count ?? 0}/${execution.managed_asset_count ?? 0} artifacts`,
    (execution.failed_count ?? 0) > 0 ? `${execution.failed_count} failed` : "",
    (execution.submitted_or_running_count ?? 0) > 0
      ? `${execution.submitted_or_running_count} running`
      : "",
    (execution.fallback_visual_count ?? 0) > 0
      ? `${execution.fallback_visual_count} fallback visuals`
      : "",
    models,
    operations,
    managedMediaOperatorActionLabel(
      report.media_readiness?.managed_media_operator_action,
    ),
  ]
    .filter(Boolean)
    .join(" · ");
}

function productionManagedMediaSmokeSummary(
  report: ProductionTestReport,
): string {
  const smoke = report.media_readiness?.managed_media_smoke;
  if (!smoke) {
    return "not checked";
  }
  if (smoke.status === "not_configured") {
    return "not configured";
  }
  const parts = [
    smoke.status ? `status ${smoke.status}` : "",
    smoke.model ? `model ${smoke.model}` : "",
    smoke.terminal_state ? `terminal ${smoke.terminal_state}` : "",
    smoke.failure_category ? `failure ${smoke.failure_category}` : "",
    managedMediaOperatorActionLabel(smoke.action),
  ].filter(Boolean);
  return parts.length ? parts.join(" · ") : "not checked";
}

function productionProviderRepairHandoffSummary(
  report: ProductionTestReport,
): string {
  const handoff = report.provider_repair_handoff;
  if (!handoff) {
    return "not checked";
  }
  if (handoff.status === "not_configured") {
    return "not configured";
  }
  if (handoff.status === "missing") {
    return `missing · ${handoff.path ?? "no path"}`;
  }
  if (handoff.status === "unreadable") {
    return `unreadable · ${handoff.error_type ?? "read error"} · ${handoff.path ?? "no path"}`;
  }
  const latestSections = handoff.latest_sections ?? [];
  const latest =
    latestSections.length > 0
      ? latestSections[latestSections.length - 1]
      : undefined;
  return [
    handoff.status ?? "unknown",
    `${handoff.section_count ?? 0} sections`,
    handoff.has_voicebox_requirements ? "voicebox noted" : "voicebox not noted",
    handoff.has_managed_media_requirements
      ? "B1 media noted"
      : "B1 media not noted",
    latest ? `latest ${latest}` : "",
    handoff.path ?? "",
  ]
    .filter(Boolean)
    .join(" · ");
}

function productionLiveProviderPreflightSummary(
  report: ProductionTestReport,
): string {
  const preflight = report.live_provider_preflight;
  if (!preflight) {
    return "not checked";
  }
  if (preflight.status === "missing") {
    return "missing · run live preflight";
  }
  const blocking = preflight.blocking_sections?.length
    ? `blocked ${preflight.blocking_sections.join(", ")}`
    : "";
  const failedModels = preflight.failed_model_ids?.length
    ? `models ${preflight.failed_model_ids.slice(0, 2).join(", ")}`
    : "";
  const failedVoices = preflight.failed_voice_profile_ids?.length
    ? `${preflight.failed_voice_profile_ids.length} failed voices`
    : "";
  return [
    preflight.status ?? "unknown",
    preflight.ready ? "ready" : "not ready",
    `${preflight.model_participant_count ?? 0} models, ${
      preflight.model_failed_count ?? 0
    } failed`,
    `${preflight.voicebox_participant_count ?? 0} voices, ${
      preflight.voicebox_failed_count ?? 0
    } failed`,
    blocking,
    failedModels,
    failedVoices,
    productionTestNextAction(preflight.action),
  ]
    .filter(Boolean)
    .join(" · ");
}

function audioOperatorActionLabel(action?: string): string {
  if (action === "plan_or_produce_speech_assets") {
    return "plan speech";
  }
  if (action === "produce_speech_assets") {
    return "produce speech";
  }
  if (action === "sync_voicebox_jobs") {
    return "sync voicebox";
  }
  if (action === "reset_cancelled_audio_assets_for_retry") {
    return "reset cancelled speech";
  }
  if (action === "produce_remaining_speech_assets") {
    return "produce remaining speech";
  }
  if (action === "fix_voicebox_generation_then_retry_audio_assets") {
    return "fix voicebox";
  }
  if (action === "audio_generation_ready") {
    return "speech ready";
  }
  if (action === "inspect_audio_generation") {
    return "inspect speech";
  }
  return "";
}

