function temporalRuntimeSummary(
  component: SystemHealthComponent | undefined,
): string {
  if (!component) {
    return "unknown";
  }
  const mode =
    typeof component.details.mode === "string"
      ? component.details.mode
      : "unknown";
  const taskQueue =
    typeof component.details.task_queue === "string" &&
    component.details.task_queue.length > 0
      ? component.details.task_queue
      : "";
  const workerActive =
    component.details.temporal_worker_active === true
      ? "worker active"
      : component.details.temporal_worker_active === false
        ? "worker idle"
        : "";
  const execution = temporalWorkerExecutionSummary(
    component.details.temporal_worker_execution,
  );
  const failedChecks = Array.isArray(component.details.failed_readiness_checks)
    ? component.details.failed_readiness_checks.filter(
        (value): value is string => typeof value === "string",
      )
    : [];
  const checks =
    component.details.readiness_checks &&
    typeof component.details.readiness_checks === "object"
      ? formatBooleanBreakdown(
          component.details.readiness_checks as Record<string, boolean>,
        )
      : "";
  return [
    mode,
    taskQueue,
    workerActive,
    execution,
    failedChecks.length ? `failed ${failedChecks.slice(0, 4).join("+")}` : "",
    checks,
  ]
    .filter(Boolean)
    .join(" / ");
}

function temporalWorkerExecutionSummary(value: unknown): string {
  if (!value || typeof value !== "object") {
    return "";
  }
  const evidence = value as Record<string, unknown>;
  const status = typeof evidence.status === "string" ? evidence.status : "";
  if (!status || status === "unknown") {
    return "";
  }
  const progressed =
    typeof evidence.progressed_stage_count === "number"
      ? `${evidence.progressed_stage_count} progressed`
      : "";
  const activities =
    typeof evidence.activity_count === "number"
      ? `${evidence.activity_count} activities`
      : "";
  const errors =
    typeof evidence.error_count === "number"
      ? `${evidence.error_count} errors`
      : "";
  return ["exec", status, progressed, activities, errors]
    .filter(Boolean)
    .join(" ");
}

function WorkerStatusPanel(props: {
  summary: WorkerStatusSummary | null;
  isLoading: boolean;
  signals: WorkerSignalRecord[];
  signalsLoading: boolean;
  isRecordingSignal: boolean;
  onRecordSignal: (draft: WorkerSignalDraft) => void;
}) {
  const counts = props.summary?.counts ?? {};
  const workers = props.summary?.workers ?? [];
  const leases = props.summary?.leases ?? [];
  const activeWorkers = workers.filter((worker) => !worker.stale);
  const staleWorkers = workers.filter((worker) => worker.stale);
  const staleWorkerRoles = staleWorkerRoleSummary(staleWorkers);
  const roleOptions = workerSignalRoleOptions(workers);
  const [showStaleWorkers, setShowStaleWorkers] = React.useState(false);
  const [draft, setDraft] = React.useState<WorkerSignalDraft>({
    targetRole: "*",
    signalType: "drain",
    reason: "",
  });

  function updateDraft<K extends keyof WorkerSignalDraft>(
    key: K,
    value: WorkerSignalDraft[K],
  ) {
    setDraft((current) => ({ ...current, [key]: value }));
  }

  function submitSignal(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    props.onRecordSignal(draft);
  }

  return (
    <section className="mediaPanel">
      <div className="sectionTitle">
        <h2>Worker Status</h2>
        <span>
          {props.isLoading ? "Loading" : (props.summary?.status ?? "unknown")}
        </span>
      </div>
      <div className="mediaStats">
        <div>
          <span>Active</span>
          <strong>{counts.active_workers ?? 0}</strong>
        </div>
        <div>
          <span>Roles</span>
          <strong>{counts.active_roles ?? 0}</strong>
        </div>
        <div>
          <span>Stale</span>
          <strong>{counts.stale_workers ?? 0}</strong>
        </div>
        <div>
          <span>Failed</span>
          <strong>{counts.failed_workers ?? 0}</strong>
        </div>
        <div>
          <span>Leases</span>
          <strong>{counts.active_leases ?? 0}</strong>
        </div>
        <div>
          <span>Retained</span>
          <strong>{counts.retained_heartbeats ?? workers.length}</strong>
        </div>
        <div>
          <span>Pruned</span>
          <strong>
            {(counts.pruned_stale_heartbeats ?? 0) +
              (counts.pruned_expired_leases ?? 0)}
          </strong>
        </div>
        <div>
          <span>Malformed</span>
          <strong>
            {(counts.malformed_heartbeats ?? 0) +
              (counts.malformed_leases ?? 0)}
          </strong>
        </div>
        <div>
          <span>Bad pruned</span>
          <strong>
            {(counts.pruned_malformed_heartbeats ?? 0) +
              (counts.pruned_malformed_leases ?? 0)}
          </strong>
        </div>
        <div>
          <span>TTL</span>
          <strong>
            {props.summary?.lease_ttl_seconds ??
              props.summary?.heartbeat_ttl_seconds ??
              0}
            s
          </strong>
        </div>
        <div>
          <span>Retention</span>
          <strong>
            {formatWorkerRetention(
              props.summary?.runtime_state_retention_seconds,
            )}
          </strong>
        </div>
      </div>
      <form className="workerSignalForm" onSubmit={submitSignal}>
        <label className="field">
          <span>Target role</span>
          <select
            value={draft.targetRole}
            onChange={(event) => updateDraft("targetRole", event.target.value)}
          >
            {roleOptions.map((role) => (
              <option key={role} value={role}>
                {role}
              </option>
            ))}
          </select>
        </label>
        <label className="field">
          <span>Signal</span>
          <select
            value={draft.signalType}
            onChange={(event) =>
              updateDraft("signalType", event.target.value as WorkerSignalType)
            }
          >
            <option value="drain">drain</option>
            <option value="resume">resume</option>
            <option value="reload">reload</option>
            <option value="stop_after_current">stop after current</option>
          </select>
        </label>
        <label className="field wide">
          <span>Reason</span>
          <input
            value={draft.reason}
            onChange={(event) => updateDraft("reason", event.target.value)}
            placeholder="maintenance window"
          />
        </label>
        <button
          className="primaryButton"
          type="submit"
          disabled={props.isRecordingSignal}
        >
          <Radio size={18} />
          Send Signal
        </button>
      </form>
      <div className="workerListHeader">
        <div>
          <strong>Active heartbeats</strong>
          <span>
            {activeWorkers.length} current · {staleWorkers.length} stale
            retained
          </span>
        </div>
        {staleWorkers.length > 0 ? (
          <button
            className="secondaryButton compact"
            type="button"
            onClick={() => setShowStaleWorkers((current) => !current)}
          >
            <History size={16} />
            {showStaleWorkers ? "Hide Stale" : "Show Stale"}
          </button>
        ) : null}
      </div>
      <div className="languageRows">
        {activeWorkers.map((worker) => (
          <article
            className="languageRow"
            key={`${worker.role}-${worker.worker_id}`}
          >
            <div>
              <strong>{worker.role}</strong>
              <span>{worker.stale ? "stale" : worker.status}</span>
            </div>
            <span>{workerSummary(worker)}</span>
          </article>
        ))}
        {!props.isLoading &&
        activeWorkers.length === 0 &&
        workers.length > 0 ? (
          <div className="emptyState compact">
            No active worker heartbeats. {staleWorkers.length} stale retained
            {staleWorkerRoles ? ` across ${staleWorkerRoles}` : ""}.
          </div>
        ) : null}
        {!showStaleWorkers && staleWorkers.length > 0 ? (
          <div className="workerStaleSummary">
            <span>{staleWorkers.length} stale retained</span>
            <strong>{staleWorkerRoles || "No role detail"}</strong>
          </div>
        ) : null}
        {showStaleWorkers
          ? staleWorkers.map((worker) => (
              <article
                className="languageRow stale"
                key={`stale-${worker.role}-${worker.worker_id}`}
              >
                <div>
                  <strong>{worker.role}</strong>
                  <span>stale</span>
                </div>
                <span>{workerSummary(worker)}</span>
              </article>
            ))
          : null}
        {!props.isLoading && workers.length === 0 ? (
          <div className="emptyState">No worker heartbeats recorded.</div>
        ) : null}
        {leases.map((lease) => (
          <article className="languageRow" key={`lease-${lease.role}`}>
            <div>
              <strong>{lease.role} lease</strong>
              <span>{lease.expired ? "expired" : "active"}</span>
            </div>
            <span>{leaseSummary(lease)}</span>
          </article>
        ))}
        {props.signals.map((signal) => (
          <article className="languageRow" key={`signal-${signal.signal_id}`}>
            <div>
              <strong>{signal.target_role} signal</strong>
              <span>{signal.signal_type}</span>
            </div>
            <span>{workerSignalSummary(signal)}</span>
          </article>
        ))}
        {!props.signalsLoading && props.signals.length === 0 ? (
          <div className="emptyState">No worker signals recorded.</div>
        ) : null}
      </div>
    </section>
  );
}

function staleWorkerRoleSummary(workers: WorkerStatusRecord[]): string {
  const counts = new Map<string, number>();
  for (const worker of workers) {
    const role = worker.role || "unknown";
    counts.set(role, (counts.get(role) ?? 0) + 1);
  }
  return Array.from(counts.entries())
    .sort(([leftRole], [rightRole]) => leftRole.localeCompare(rightRole))
    .map(([role, count]) => `${role} ${count}`)
    .join(" · ");
}

function workerSignalRoleOptions(workers: WorkerStatusRecord[]): string[] {
  return [
    "*",
    ...Array.from(
      new Set(workers.map((worker) => worker.role).filter(Boolean)),
    ).sort(),
    "voicebox-adapter",
    "comfyui-adapter",
    "discussion-worker",
    "research-worker",
    "localization-worker",
    "qc-worker",
    "timeline-worker",
    "render-worker",
    "publishing-worker",
    "workflow-worker",
    "temporal-worker",
  ].filter((role, index, roles) => roles.indexOf(role) === index);
}

function workerSummary(worker: WorkerStatusRecord): string {
  const signal = worker.details.worker_signal;
  if (
    worker.details.signal_skipped === true &&
    typeof signal === "object" &&
    signal !== null
  ) {
    const signalType =
      "signal_type" in signal ? String(signal.signal_type) : "signal";
    return `${Math.round(worker.heartbeat_age_seconds)}s ago · skipped by ${signalType}`;
  }
  const pendingAudio = worker.details.pending_audio_assets;
  const pendingVisual = worker.details.pending_visual_assets;
  if (typeof pendingAudio === "number") {
    return `${Math.round(worker.heartbeat_age_seconds)}s ago · ${pendingAudio} audio pending`;
  }
  if (typeof pendingVisual === "number") {
    return `${Math.round(worker.heartbeat_age_seconds)}s ago · ${pendingVisual} visual pending`;
  }
  return `${Math.round(worker.heartbeat_age_seconds)}s ago · ${worker.worker_id}`;
}

function leaseSummary(lease: WorkerLeaseRecord): string {
  if (lease.expired) {
    return `${lease.worker_id} · expired ${Math.abs(Math.round(lease.expires_in_seconds))}s ago`;
  }
  return `${lease.worker_id} · ${Math.round(lease.expires_in_seconds)}s left`;
}

function formatWorkerRetention(seconds?: number): string {
  if (!seconds || seconds <= 0) {
    return "0s";
  }
  if (seconds < 60) {
    return `${Math.round(seconds)}s`;
  }
  const minutes = seconds / 60;
  if (minutes < 60) {
    return `${Math.round(minutes)}m`;
  }
  const hours = minutes / 60;
  if (hours < 48) {
    return `${Math.round(hours)}h`;
  }
  return `${Math.round(hours / 24)}d`;
}

function workerSignalSummary(signal: WorkerSignalRecord): string {
  const sources =
    signal.delivery_sources?.join("+") || signal.redis_stream || "runtime";
  const stream = signal.redis_stream_id ? ` · ${signal.redis_stream_id}` : "";
  const reason = signal.reason ? ` · ${signal.reason}` : "";
  return `${signal.status} · ${sources}${stream}${reason}`;
}

function BackupStatusPanel(props: {
  backupHealth: SystemHealthComponent | null;
  backups: BackupManifest[];
  isLoading: boolean;
  isCreating: boolean;
  onCreate: () => void;
  isValidating: boolean;
  latestValidation: BackupRestoreValidation | null;
  onValidate: (backup: BackupManifest) => void;
}) {
  const latest = props.backups[0] ?? null;
  const backupDetails = props.backupHealth?.details ?? {};
  const latestHealthArchive = backupHealthLatestArchive(props.backupHealth);
  const archiveCount =
    typeof backupDetails.archive_count === "number"
      ? backupDetails.archive_count
      : props.backups.length;
  const validatedArchiveCount = nestedNumber(
    backupDetails,
    "restore_validated_archive_count",
  );
  const unvalidatedArchiveCount = nestedNumber(
    backupDetails,
    "restore_unvalidated_archive_count",
  );
  const manifestStatus =
    latestHealthArchive?.manifest_readable === true
      ? "readable"
      : latestHealthArchive
        ? "unreadable"
        : (props.backupHealth?.status ?? "unknown");
  return (
    <section className="mediaPanel">
      <div className="sectionTitle">
        <h2>Backups</h2>
        <span>
          {props.backupHealth?.status ??
            (props.isLoading ? "Loading" : "unknown")}
        </span>
      </div>
      <div className="mediaStats">
        <div>
          <span>Archives</span>
          <strong>{archiveCount}</strong>
        </div>
        <div>
          <span>Validated</span>
          <strong>
            {validatedArchiveCount}/
            {validatedArchiveCount + unvalidatedArchiveCount}
          </strong>
        </div>
        <div>
          <span>Manifest</span>
          <strong>{manifestStatus}</strong>
        </div>
        <div>
          <span>Latest Age</span>
          <strong>{formatBackupArchiveAge(latestHealthArchive)}</strong>
        </div>
        <div>
          <span>Database</span>
          <strong>{latest?.database.total_records ?? 0}</strong>
        </div>
        <div>
          <span>Objects</span>
          <strong>{latest?.object_storage.file_count ?? 0}</strong>
        </div>
        <div>
          <span>Runtime</span>
          <strong>{latest?.runtime_state.file_count ?? 0}</strong>
        </div>
        <div>
          <span>Archive</span>
          <strong>{formatBytes(latest?.archive.size_bytes ?? 0)}</strong>
        </div>
      </div>
      <div className="backupActions">
        <button
          className="secondaryButton"
          disabled={props.isCreating}
          onClick={props.onCreate}
        >
          <Save size={18} />
          Create Backup
        </button>
        <button
          className="secondaryButton"
          disabled={!latest || props.isValidating}
          onClick={() => latest && props.onValidate(latest)}
        >
          <CheckCircle2 size={18} />
          Validate Latest
        </button>
        <span>{backupHealthSummary(props.backupHealth, latest)}</span>
      </div>
      <div className="languageRows">
        {props.latestValidation ? (
          <article className="languageRow">
            <div>
              <strong>restore validation</strong>
              <span>{props.latestValidation.status}</span>
            </div>
            <span>
              {backupRestoreValidationSummary(props.latestValidation)}
            </span>
          </article>
        ) : null}
        {props.backupHealth ? (
          <article className="languageRow">
            <div>
              <strong>backup_storage</strong>
              <span>{props.backupHealth.status}</span>
            </div>
            <span>{componentSummary(props.backupHealth)}</span>
          </article>
        ) : null}
        {props.backups.slice(0, 3).map((backup) => (
          <article className="languageRow" key={backup.backup_id}>
            <div>
              <strong>{backup.label ?? backup.backup_id}</strong>
              <span>{formatAuditTime(backup.created_at)}</span>
            </div>
            <span>{backupSummary(backup)}</span>
          </article>
        ))}
        {!props.isLoading && props.backups.length === 0 ? (
          <div className="emptyState">No backup archives found.</div>
        ) : null}
      </div>
    </section>
  );
}

function backupHealthLatestArchive(
  component: SystemHealthComponent | null,
): Record<string, unknown> | null {
  const archive = component?.details.latest_archive;
  if (!archive || typeof archive !== "object") {
    return null;
  }
  return archive as Record<string, unknown>;
}

function backupHealthLatestRestoreValidation(
  component: SystemHealthComponent | null,
): Record<string, unknown> | null {
  const validation = component?.details.latest_restore_validation;
  if (!validation || typeof validation !== "object") {
    return null;
  }
  return validation as Record<string, unknown>;
}

function backupHealthSummary(
  component: SystemHealthComponent | null,
  latest: BackupManifest | null,
): string {
  const details = component?.details ?? {};
  const reason = typeof details.reason === "string" ? details.reason : "";
  const path = typeof details.path === "string" ? details.path : "";
  const archive = backupHealthLatestArchive(component);
  const validation = backupHealthLatestRestoreValidation(component);
  const filename =
    typeof archive?.filename === "string"
      ? archive.filename
      : (latest?.archive.filename ?? "no archive");
  const validationStatus =
    validation?.validated === true
      ? "restore validated"
      : validation
        ? "restore validation missing"
        : "";
  return [filename, validationStatus, reason, path].filter(Boolean).join(" · ");
}

function formatBackupArchiveAge(
  archive: Record<string, unknown> | null,
): string {
  const ageSeconds = archive?.age_seconds;
  if (typeof ageSeconds !== "number") {
    return "n/a";
  }
  return formatWorkerRetention(ageSeconds);
}

function backupRestoreValidationSummary(
  validation: BackupRestoreValidation,
): string {
  const plan = validation.restore_plan;
  const summary = plan?.summary ?? {};
  const database = plan?.database;
  const objectStorage = plan?.object_storage;
  const runtimeState = plan?.runtime_state;
  const scopes =
    typeof summary.target_scope_count === "number"
      ? summary.target_scope_count
      : 0;
  const records =
    typeof summary.target_record_count === "number"
      ? summary.target_record_count
      : 0;
  const files =
    typeof summary.target_file_count === "number"
      ? summary.target_file_count
      : 0;
  const targets = [
    database?.will_restore === true ? "database" : "",
    objectStorage?.will_restore === true ? "objects" : "",
    runtimeState?.will_restore === true ? "runtime" : "",
  ].filter(Boolean);
  const objectValidation = backupContentValidationSummary(
    objectStorage?.archive_validation,
    "objects",
  );
  const runtimeValidation = backupContentValidationSummary(
    runtimeState?.archive_validation,
    "runtime",
  );
  return [
    plan?.backup_id ?? "",
    `${scopes} scopes`,
    `${records} records`,
    `${files} files`,
    targets.join("+"),
    objectValidation,
    runtimeValidation,
  ]
    .filter(Boolean)
    .join(" · ");
}

function backupSummary(backup: BackupManifest): string {
  const objectSource =
    backup.object_storage.source === "s3_bucket" ? "S3 objects" : "files";
  const validation =
    backup.restore_validation?.validated === true
      ? `validated ${formatBackupValidationAge(backup.restore_validation)}`
      : "not validated";
  return `${backup.database.total_records} records · ${backup.object_storage.file_count} ${objectSource} · ${formatBytes(backup.archive.size_bytes)} · ${validation}`;
}

function formatBackupValidationAge(
  validation: BackupManifest["restore_validation"],
): string {
  if (!validation || typeof validation.validation_age_seconds !== "number") {
    return "";
  }
  return formatWorkerRetention(validation.validation_age_seconds);
}

function defaultLanguageProfileDraft(): LanguageProfileDraft {
  return {
    originalId: null,
    id: "",
    name: "",
    bcp47_tag: "en",
    native_name: "",
    default_mode: "localized_reperformance",
    subtitle_direction: "ltr",
    enabled: true,
    lineBreakingJson: '{\n  "max_chars_per_line": 42,\n  "max_lines": 2\n}',
    voiceDefaultsJson: '{\n  "speaking_rate": 1\n}',
  };
}

function languageProfileToDraft(
  profile: LanguageProfile,
): LanguageProfileDraft {
  return {
    originalId: profile.id,
    id: profile.id,
    name: profile.name,
    bcp47_tag: profile.bcp47_tag,
    native_name: profile.native_name ?? "",
    default_mode: profile.default_mode,
    subtitle_direction: profile.subtitle_direction,
    enabled: profile.enabled,
    lineBreakingJson: JSON.stringify(profile.line_breaking ?? {}, null, 2),
    voiceDefaultsJson: JSON.stringify(profile.voice_defaults ?? {}, null, 2),
  };
}

function LanguageProfilePanel(props: {
  profiles: LanguageProfile[];
  projects: Project[];
  episodes: EpisodeSummary[];
  voiceProfiles: VoiceProfile[];
  isDeleting: boolean;
  isLoading: boolean;
  isSaving: boolean;
  onDelete: (profileId: string) => void;
  onSave: (payload: {
    originalId: string | null;
    profile: Record<string, unknown>;
  }) => void;
}) {
  const [draft, setDraft] = React.useState<LanguageProfileDraft>(
    defaultLanguageProfileDraft,
  );
  const [error, setError] = React.useState<string | null>(null);
  const updateDraft = <K extends keyof LanguageProfileDraft>(
    key: K,
    value: LanguageProfileDraft[K],
  ) => {
    setDraft((current) => ({ ...current, [key]: value }));
  };
  const usage = React.useMemo(() => {
    const counts = new Map<string, number>();
    const bump = (language?: string | null) => {
      if (!language) {
        return;
      }
      counts.set(language, (counts.get(language) ?? 0) + 1);
    };
    props.projects.forEach((project) => bump(project.default_language));
    props.voiceProfiles.forEach((profile) => bump(profile.language));
    props.episodes.forEach((episode) => {
      bump(episode.source_language);
      episode.output_languages.forEach((language) => bump(language));
    });
    return counts;
  }, [props.episodes, props.projects, props.voiceProfiles]);
  const saveLanguage = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError(null);
    try {
      props.onSave({
        originalId: draft.originalId,
        profile: {
          id: draft.id.trim(),
          name: draft.name.trim(),
          bcp47_tag: draft.bcp47_tag.trim(),
          native_name: draft.native_name.trim(),
          default_mode: draft.default_mode.trim() || "localized_reperformance",
          subtitle_direction: draft.subtitle_direction.trim() || "ltr",
          enabled: draft.enabled,
          line_breaking: parseJsonObjectDraft(
            draft.lineBreakingJson,
            "Line breaking",
          ),
          voice_defaults: parseJsonObjectDraft(
            draft.voiceDefaultsJson,
            "Voice defaults",
          ),
        },
      });
    } catch (exc) {
      setError(
        exc instanceof Error ? exc.message : "Invalid language profile JSON",
      );
    }
  };
  return (
    <section className="mediaPanel">
      <div className="sectionTitle">
        <h2>Languages</h2>
        <button
          className="iconButton"
          onClick={() => {
            setDraft(defaultLanguageProfileDraft());
            setError(null);
          }}
          title="New language"
          type="button"
        >
          <Plus size={16} />
        </button>
      </div>
      <form className="modelEndpointForm" onSubmit={saveLanguage}>
        <label className="field">
          <span>ID</span>
          <input
            disabled={draft.originalId !== null}
            maxLength={128}
            required
            value={draft.id}
            onChange={(event) => updateDraft("id", event.target.value)}
          />
        </label>
        <label className="field">
          <span>Name</span>
          <input
            required
            value={draft.name}
            onChange={(event) => updateDraft("name", event.target.value)}
          />
        </label>
        <label className="field">
          <span>Tag</span>
          <input
            maxLength={12}
            minLength={2}
            required
            value={draft.bcp47_tag}
            onChange={(event) => updateDraft("bcp47_tag", event.target.value)}
          />
        </label>
        <label className="field">
          <span>Native Name</span>
          <input
            value={draft.native_name}
            onChange={(event) => updateDraft("native_name", event.target.value)}
          />
        </label>
        <label className="field">
          <span>Mode</span>
          <select
            value={draft.default_mode}
            onChange={(event) =>
              updateDraft("default_mode", event.target.value)
            }
          >
            <option value="canonical">canonical</option>
            <option value="translation">translation</option>
            <option value="localized_reperformance">
              localized_reperformance
            </option>
          </select>
        </label>
        <label className="field">
          <span>Direction</span>
          <select
            value={draft.subtitle_direction}
            onChange={(event) =>
              updateDraft("subtitle_direction", event.target.value)
            }
          >
            <option value="ltr">ltr</option>
            <option value="rtl">rtl</option>
          </select>
        </label>
        <label className="field wide">
          <span>Line Breaking</span>
          <textarea
            rows={4}
            value={draft.lineBreakingJson}
            onChange={(event) =>
              updateDraft("lineBreakingJson", event.target.value)
            }
          />
        </label>
        <label className="field wide">
          <span>Voice Defaults</span>
          <textarea
            rows={4}
            value={draft.voiceDefaultsJson}
            onChange={(event) =>
              updateDraft("voiceDefaultsJson", event.target.value)
            }
          />
        </label>
        <label className="toggleField">
          <input
            checked={draft.enabled}
            type="checkbox"
            onChange={(event) => updateDraft("enabled", event.target.checked)}
          />
          Enabled
        </label>
        <div className="modelEndpointActions">
          <span>
            {error ?? (draft.originalId ? "editing language" : "new language")}
          </span>
          <button
            className="iconButton"
            disabled={props.isSaving || !draft.id.trim() || !draft.name.trim()}
            title="Save language"
            type="submit"
          >
            <Save size={16} />
          </button>
        </div>
      </form>
      <div className="languageRows">
        {props.profiles.map((profile) => {
          const linked = usage.get(profile.bcp47_tag) ?? 0;
          return (
            <article className="languageRow" key={profile.id}>
              <div>
                <strong>{profile.name}</strong>
                <span>
                  {profile.bcp47_tag} · {profile.default_mode} ·{" "}
                  {profile.subtitle_direction}
                </span>
              </div>
              <div className="turnActions">
                <span>{linked} uses</span>
                <button
                  className="iconButton"
                  onClick={() => {
                    setDraft(languageProfileToDraft(profile));
                    setError(null);
                  }}
                  title="Edit language"
                  type="button"
                >
                  <SlidersHorizontal size={16} />
                </button>
                <button
                  className="iconButton danger"
                  disabled={props.isDeleting || linked > 0}
                  onClick={() => props.onDelete(profile.id)}
                  title="Delete language"
                  type="button"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </article>
          );
        })}
        {!props.isLoading && props.profiles.length === 0 ? (
          <div className="emptyState">No language profiles configured.</div>
        ) : null}
      </div>
    </section>
  );
}

function defaultProjectDraft(): ProjectDraft {
  return {
    originalId: null,
    name: "",
    description: "",
    default_language: "en",
    default_show_format_id: "analytical_panel_v1",
    show_name: "",
  };
}

function projectToDraft(project: Project): ProjectDraft {
  return {
    originalId: project.id,
    name: project.name,
    description: project.description,
    default_language: project.default_language,
    default_show_format_id: project.default_show_format_id,
    show_name: project.branding?.show_name ?? "",
  };
}

function ProjectPanel(props: {
  projects: Project[];
  episodes: EpisodeSummary[];
  isDeleting: boolean;
  isLoading: boolean;
  isSaving: boolean;
  isUploadingLogo: boolean;
  onDelete: (projectId: string) => void;
  onSave: (payload: {
    originalId: string | null;
    project: Record<string, unknown>;
  }) => void;
  onUploadLogo: (projectId: string, file: File) => void;
}) {
  const [draft, setDraft] = React.useState<ProjectDraft>(defaultProjectDraft);
  const updateDraft = <K extends keyof ProjectDraft>(
    key: K,
    value: ProjectDraft[K],
  ) => {
    setDraft((current) => ({ ...current, [key]: value }));
  };
  const episodeCounts = React.useMemo(() => {
    const counts = new Map<string, number>();
    for (const episode of props.episodes) {
      if (episode.project_id) {
        counts.set(
          episode.project_id,
          (counts.get(episode.project_id) ?? 0) + 1,
        );
      }
    }
    return counts;
  }, [props.episodes]);
  const saveProject = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const existingProject = props.projects.find((project) => project.id === draft.originalId);
    props.onSave({
      originalId: draft.originalId,
      project: {
        name: draft.name.trim(),
        description: draft.description.trim(),
        default_language: draft.default_language.trim() || "en",
        default_show_format_id:
          draft.default_show_format_id.trim() || "analytical_panel_v1",
        branding: {
          show_name: draft.show_name.trim() || null,
          logo: existingProject?.branding?.logo ?? null,
        },
      },
    });
  };
  return (
    <section className="mediaPanel">
      <div className="sectionTitle">
        <h2>Projects</h2>
        <button
          className="secondaryButton compact"
          onClick={() => setDraft(defaultProjectDraft())}
          type="button"
        >
          <Plus size={16} />
          New project
        </button>
      </div>
      <form className="modelEndpointForm" onSubmit={saveProject}>
        <label className="field">
          <span>Name</span>
          <input
            required
            value={draft.name}
            onChange={(event) => updateDraft("name", event.target.value)}
          />
        </label>
        <label className="field">
          <span>Language</span>
          <input
            maxLength={12}
            minLength={2}
            required
            value={draft.default_language}
            onChange={(event) =>
              updateDraft("default_language", event.target.value)
            }
          />
        </label>
        <label className="field wide">
          <span>Show Format</span>
          <input
            required
            value={draft.default_show_format_id}
            onChange={(event) =>
              updateDraft("default_show_format_id", event.target.value)
            }
          />
        </label>
        <label className="field wide">
          <span>Description</span>
          <textarea
            rows={3}
            value={draft.description}
            onChange={(event) => updateDraft("description", event.target.value)}
          />
        </label>
        <label className="field wide">
          <span>Show name on the studio screen</span>
          <input
            maxLength={256}
            placeholder="Uses the project name when empty"
            value={draft.show_name}
            onChange={(event) => updateDraft("show_name", event.target.value)}
          />
        </label>
        <label className="field wide">
          <span>Show logo</span>
          <input
            accept="image/png,image/jpeg,image/webp"
            disabled={!draft.originalId || props.isUploadingLogo}
            type="file"
            onChange={(event) => {
              const file = event.target.files?.[0];
              if (file && draft.originalId) props.onUploadLogo(draft.originalId, file);
              event.currentTarget.value = "";
            }}
          />
          <small>
            {draft.originalId
              ? "PNG, JPEG, or WebP; normalized and stored immutably."
              : "Save the project before uploading its logo."}
          </small>
        </label>
        <div className="modelEndpointActions">
          <span>{draft.originalId ? "editing project" : "new project"}</span>
          <button
            className="primaryButton compact"
            disabled={props.isSaving || !draft.name.trim()}
            type="submit"
          >
            <Save size={16} />
            Save project
          </button>
        </div>
      </form>
      <div className="languageRows">
        {props.projects.map((project) => {
          const linkedEpisodes = episodeCounts.get(project.id) ?? 0;
          return (
            <article className="languageRow" key={project.id}>
              <div>
                <strong>{project.name}</strong>
                <span>
                  {project.default_language} · {project.default_show_format_id} ·{" "}
                  {project.branding?.logo ? "custom logo" : "bundled logo"}
                </span>
              </div>
              <div className="turnActions">
                <span>{linkedEpisodes} episodes</span>
                <button
                  className="iconButton"
                  onClick={() => setDraft(projectToDraft(project))}
                  title="Edit project"
                  type="button"
                >
                  <SlidersHorizontal size={16} />
                </button>
                <button
                  className="iconButton danger"
                  disabled={props.isDeleting || linkedEpisodes > 0}
                  onClick={() => props.onDelete(project.id)}
                  title="Delete project"
                  type="button"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </article>
          );
        })}
        {!props.isLoading && props.projects.length === 0 ? (
          <div className="emptyState">No projects configured.</div>
        ) : null}
      </div>
    </section>
  );
}

function formatBytes(value: number): string {
  if (value >= 1024 * 1024) {
    return `${(value / (1024 * 1024)).toFixed(1)} MB`;
  }
  if (value >= 1024) {
    return `${(value / 1024).toFixed(1)} KB`;
  }
  return `${value} B`;
}

function SecurityPolicyPanel(props: {
  policy: AuthPolicy | null;
  isLoading: boolean;
  revocations: ProviderSessionRevocation[];
  revocationsLoading: boolean;
  decisions: ProviderSessionDecision[];
  decisionsLoading: boolean;
  revocationPending: boolean;
  browserSession: BrowserAuthSession;
  onRecordRevocation: (payload: Record<string, unknown>) => void;
  onSaveBrowserSession: (session: BrowserAuthSession) => void;
}) {
  const roles = props.policy?.roles ?? {};
  const apiKeyMode = props.policy?.authentication_modes?.api_key;
  const trustedIdentityMode =
    props.policy?.authentication_modes?.trusted_identity;
  const providerSessionMode =
    props.policy?.authentication_modes?.provider_session;
  const [sessionMode, setSessionMode] = React.useState<BrowserAuthMode>(
    props.browserSession.mode,
  );
  const [bearerToken, setBearerToken] = React.useState(
    props.browserSession.bearerToken ?? "",
  );
  const [browserApiKey, setBrowserApiKey] = React.useState(
    props.browserSession.apiKey ?? "",
  );
  const [browserRole, setBrowserRole] = React.useState(
    props.browserSession.role ?? "admin",
  );
  const [browserUserId, setBrowserUserId] = React.useState(
    props.browserSession.userId ?? "browser-operator",
  );
  const [revocationDraft, setRevocationDraft] =
    React.useState<ProviderSessionRevocationDraft>({
      token_sha256: "",
      jti: "",
      subject: "",
      reason: "",
      expires_at: "",
      user_id: "browser-operator",
    });
  const [revocationError, setRevocationError] = React.useState<string | null>(
    null,
  );
  const providerTokenHeader =
    providerSessionMode?.token_header ??
    props.policy?.headers.provider_session_token ??
    "authorization";
  const apiKeyHeader =
    apiKeyMode?.header ??
    props.policy?.headers.api_key ??
    "x-dialecticore-api-key";
  const roleHeader = props.policy?.headers.role ?? "x-dialecticore-role";
  const userHeader = props.policy?.headers.user ?? "x-dialecticore-user";
  const roleOptions = Object.keys(roles);
  const saveDisabled =
    (sessionMode === "provider_session" && bearerToken.trim().length === 0) ||
    (sessionMode === "api_key" && browserApiKey.trim().length === 0);
  const activeSessionLabel =
    props.browserSession.mode === "provider_session"
      ? "bearer"
      : props.browserSession.mode === "api_key"
        ? (props.browserSession.role ?? "api key")
        : "none";

  React.useEffect(() => {
    setSessionMode(props.browserSession.mode);
    setBearerToken(props.browserSession.bearerToken ?? "");
    setBrowserApiKey(props.browserSession.apiKey ?? "");
    setBrowserRole(props.browserSession.role ?? "admin");
    setBrowserUserId(props.browserSession.userId ?? "browser-operator");
  }, [props.browserSession]);

  function saveBrowserSession(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (sessionMode === "none") {
      props.onSaveBrowserSession(emptyBrowserAuthSession);
      return;
    }
    if (sessionMode === "provider_session") {
      props.onSaveBrowserSession({
        mode: "provider_session",
        bearerToken: bearerToken.trim(),
        providerTokenHeader,
      });
      return;
    }
    props.onSaveBrowserSession({
      mode: "api_key",
      apiKey: browserApiKey.trim(),
      apiKeyHeader,
      role: browserRole.trim() || "viewer",
      roleHeader,
      userId: browserUserId.trim() || undefined,
      userHeader,
    });
  }
  const updateRevocationDraft = <
    K extends keyof ProviderSessionRevocationDraft,
  >(
    key: K,
    value: ProviderSessionRevocationDraft[K],
  ) => {
    setRevocationError(null);
    setRevocationDraft((current) => ({ ...current, [key]: value }));
  };
  function recordRevocation(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const token_sha256 = revocationDraft.token_sha256.trim();
    const jti = revocationDraft.jti.trim();
    const subject = revocationDraft.subject.trim();
    if (!token_sha256 && !jti && !subject) {
      setRevocationError("Provide a token hash, JTI, or subject.");
      return;
    }
    if (
      token_sha256 &&
      token_sha256.length !== 64 &&
      token_sha256.length !== 71
    ) {
      setRevocationError(
        "Token hash must be 64 hex chars or sha256:<64 hex chars>.",
      );
      return;
    }
    props.onRecordRevocation({
      token_sha256: token_sha256 || null,
      jti: jti || null,
      subject: subject || null,
      reason: revocationDraft.reason.trim() || null,
      expires_at: revocationDraft.expires_at
        ? new Date(revocationDraft.expires_at).toISOString()
        : null,
      user_id: revocationDraft.user_id.trim() || "browser-operator",
    });
    setRevocationDraft({
      token_sha256: "",
      jti: "",
      subject: "",
      reason: "",
      expires_at: "",
      user_id: revocationDraft.user_id.trim() || "browser-operator",
    });
  }

  return (
    <section className="mediaPanel">
      <div className="sectionTitle">
        <h2>Security</h2>
        <span>
          {props.isLoading
            ? "Loading"
            : props.policy?.enabled
              ? "RBAC enabled"
              : "RBAC off"}
        </span>
      </div>
      <div className="mediaStats">
        <div>
          <span>Roles</span>
          <strong>{Object.keys(roles).length}</strong>
        </div>
        <div>
          <span>Permissions</span>
          <strong>{props.policy?.permissions.length ?? 0}</strong>
        </div>
        <div>
          <span>API Key Ref</span>
          <strong>
            {(apiKeyMode?.reference_configured ??
            props.policy?.api_key_reference_configured)
              ? "set"
              : "none"}
          </strong>
        </div>
        <div>
          <span>Identity</span>
          <strong>
            {(trustedIdentityMode?.enabled ??
            props.policy?.trusted_identity_enabled)
              ? "trusted"
              : "off"}
          </strong>
        </div>
        <div>
          <span>Session</span>
          <strong>
            {(providerSessionMode?.enabled ??
            props.policy?.provider_session_enabled)
              ? "provider"
              : "off"}
          </strong>
        </div>
        <div>
          <span>Revoked</span>
          <strong>
            {providerSessionMode?.revocation_registry?.active_count ?? 0}
          </strong>
        </div>
        <div>
          <span>Decisions</span>
          <strong>
            {providerSessionMode?.decision_log?.retained_count ??
              props.decisions.length}
          </strong>
        </div>
        <div>
          <span>Group Map</span>
          <strong>
            {(providerSessionMode?.group_role_map_configured ??
              props.policy?.provider_session_group_role_map_configured) ||
            (trustedIdentityMode?.group_role_map_configured ??
              props.policy?.trusted_identity_group_role_map_configured)
              ? "set"
              : "none"}
          </strong>
        </div>
      </div>
      <form className="browserAuthForm" onSubmit={saveBrowserSession}>
        <label className="field">
          <span>Browser Session</span>
          <select
            value={sessionMode}
            onChange={(event) =>
              setSessionMode(event.target.value as BrowserAuthMode)
            }
          >
            <option value="none">None</option>
            <option value="provider_session">Provider bearer</option>
            <option value="api_key">API key</option>
          </select>
        </label>
        {sessionMode === "provider_session" ? (
          <label className="field wide">
            <span>{providerTokenHeader}</span>
            <input
              type="password"
              autoComplete="off"
              value={bearerToken}
              onChange={(event) => setBearerToken(event.target.value)}
            />
          </label>
        ) : null}
        {sessionMode === "api_key" ? (
          <>
            <label className="field wide">
              <span>{apiKeyHeader}</span>
              <input
                type="password"
                autoComplete="off"
                value={browserApiKey}
                onChange={(event) => setBrowserApiKey(event.target.value)}
              />
            </label>
            <label className="field">
              <span>{roleHeader}</span>
              {roleOptions.length ? (
                <select
                  value={browserRole}
                  onChange={(event) => setBrowserRole(event.target.value)}
                >
                  {roleOptions.map((role) => (
                    <option key={role} value={role}>
                      {role}
                    </option>
                  ))}
                </select>
              ) : (
                <input
                  value={browserRole}
                  onChange={(event) => setBrowserRole(event.target.value)}
                />
              )}
            </label>
            <label className="field">
              <span>{userHeader}</span>
              <input
                value={browserUserId}
                onChange={(event) => setBrowserUserId(event.target.value)}
              />
            </label>
          </>
        ) : null}
        <div className="browserAuthActions">
          <span>{activeSessionLabel}</span>
          <button
            className="secondaryButton"
            type="submit"
            disabled={saveDisabled}
          >
            <KeyRound size={18} />
            Save
          </button>
          <button
            className="secondaryButton"
            type="button"
            onClick={() => props.onSaveBrowserSession(emptyBrowserAuthSession)}
          >
            <LogOut size={18} />
            Logout
          </button>
        </div>
      </form>
      <div className="languageRows">
        {providerSessionMode?.enabled ? (
          <>
            <form className="browserAuthForm" onSubmit={recordRevocation}>
              <label className="field wide">
                <span>Token SHA-256</span>
                <input
                  value={revocationDraft.token_sha256}
                  onChange={(event) =>
                    updateRevocationDraft("token_sha256", event.target.value)
                  }
                />
              </label>
              <label className="field">
                <span>JTI</span>
                <input
                  value={revocationDraft.jti}
                  onChange={(event) =>
                    updateRevocationDraft("jti", event.target.value)
                  }
                />
              </label>
              <label className="field">
                <span>Subject</span>
                <input
                  value={revocationDraft.subject}
                  onChange={(event) =>
                    updateRevocationDraft("subject", event.target.value)
                  }
                />
              </label>
              <label className="field wide">
                <span>Reason</span>
                <input
                  value={revocationDraft.reason}
                  onChange={(event) =>
                    updateRevocationDraft("reason", event.target.value)
                  }
                />
              </label>
              <label className="field">
                <span>Expires At</span>
                <input
                  type="datetime-local"
                  value={revocationDraft.expires_at}
                  onChange={(event) =>
                    updateRevocationDraft("expires_at", event.target.value)
                  }
                />
              </label>
              <label className="field">
                <span>Operator</span>
                <input
                  value={revocationDraft.user_id}
                  onChange={(event) =>
                    updateRevocationDraft("user_id", event.target.value)
                  }
                />
              </label>
              <div className="browserAuthActions">
                <span>
                  {revocationError ??
                    `${props.revocations.length} active revocations`}
                </span>
                <button
                  className="secondaryButton"
                  disabled={props.revocationPending}
                  type="submit"
                >
                  <ShieldAlert size={18} />
                  Revoke
                </button>
              </div>
            </form>
            {props.revocations.map((revocation) => (
              <article className="languageRow" key={revocation.revocation_id}>
                <div>
                  <strong>
                    {revocation.subject ?? revocation.jti ?? "token hash"}
                  </strong>
                  <span>
                    {revocation.reason ?? "no reason"} ·{" "}
                    {formatAuditTime(revocation.created_at)}
                  </span>
                </div>
                <span>
                  {revocation.expires_at
                    ? `expires ${formatAuditTime(revocation.expires_at)}`
                    : "no expiry"}
                </span>
              </article>
            ))}
            {!props.revocationsLoading && props.revocations.length === 0 ? (
              <div className="emptyState">
                No active provider-session revocations.
              </div>
            ) : null}
            {props.decisions.map((decision) => (
              <article className="languageRow" key={decision.decision_id}>
                <div>
                  <strong>
                    {decision.subject ??
                      decision.user_id ??
                      decision.jti ??
                      `hash ${decision.token_sha256.slice(-12)}`}
                  </strong>
                  <span>
                    {decision.status} · {decision.permission} ·{" "}
                    {formatAuditTime(decision.created_at)}
                  </span>
                </div>
                <span>
                  {decision.role ?? "no role"} · {decision.reason}
                </span>
              </article>
            ))}
            {!props.decisionsLoading && props.decisions.length === 0 ? (
              <div className="emptyState">
                No provider-session decisions recorded.
              </div>
            ) : null}
          </>
        ) : null}
        {providerSessionMode?.enabled ? (
          <article className="languageRow">
            <div>
              <strong>provider session</strong>
              <span>{providerSessionMode.token_header ?? "authorization"}</span>
            </div>
            <span>
              {providerSessionMode.mapped_groups?.length
                ? `${providerSessionMode.mapped_groups.length} mapped groups`
                : `default ${providerSessionMode.default_role ?? "viewer"}`}
            </span>
          </article>
        ) : null}
        {trustedIdentityMode?.enabled ? (
          <article className="languageRow">
            <div>
              <strong>trusted identity</strong>
              <span>
                {trustedIdentityMode.identity_header ?? "identity header"}
              </span>
            </div>
            <span>
              {trustedIdentityMode.mapped_groups?.length
                ? `${trustedIdentityMode.mapped_groups.length} mapped groups`
                : `default ${trustedIdentityMode.default_role ?? "viewer"}`}
            </span>
          </article>
        ) : null}
        {Object.entries(roles).map(([role, permissions]) => (
          <article className="languageRow" key={role}>
            <div>
              <strong>{role}</strong>
              <span>
                {permissions.includes("*")
                  ? "all permissions"
                  : `${permissions.length} permissions`}
              </span>
            </div>
            <span>
              {permissions.includes("*")
                ? "all"
                : permissions.slice(0, 4).join(", ")}
            </span>
          </article>
        ))}
        {!props.isLoading && Object.keys(roles).length === 0 ? (
          <div className="emptyState">No RBAC policy available.</div>
        ) : null}
      </div>
    </section>
  );
}

function RecentAudit(props: { events: AuditEvent[]; isLoading: boolean }) {
  return (
    <aside className="auditPanel">
      <div className="sectionTitle">
        <h2>Recent Audit</h2>
        <span>{props.isLoading ? "Loading" : props.events.length}</span>
      </div>
      {props.events.map((event) => (
        <article className="auditRow" key={event.id}>
          <div>
            <strong>{event.event_type}</strong>
            <span>{event.actor}</span>
          </div>
          <time>{formatAuditTime(event.created_at)}</time>
        </article>
      ))}
      {!props.isLoading && props.events.length === 0 ? (
        <div className="emptyState">No audit events recorded.</div>
      ) : null}
    </aside>
  );
}

function formatAuditTime(value: string): string {
  return new Date(value).toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

function TranscriptReview(props: {
  episode: Episode | null;
  canEdit: boolean;
  bridgeRevisionCreated: boolean;
  actionPending: boolean;
  onRegenerate: (turnId: string) => void;
  onCreatePostPrimerBridge: () => void;
  onReopenForEditing: () => void;
  onExclude: (turnId: string) => void;
  onEditText: (turnId: string, text: string) => void;
}) {
  const broadcastTranscripts = props.episode?.transcripts.filter(
    (item) => item.type === "broadcast",
  );
  const transcript = props.episode
    ? canonicalTranscript(props.episode) ??
      broadcastTranscripts?.[broadcastTranscripts.length - 1]
    : undefined;
  const qc = latestTranscriptQc(props.episode);
  const claimQc = latestClaimCitationQcForTranscript(props.episode, transcript);
  const durationQc = latestDurationQc(props.episode);
  const turns = transcript?.turns ?? [];
  const transcriptTurnNumbers = new Map(
    turns.map((turn, index) => [turn.id, index + 1]),
  );
  const claimIssues = claimQc?.details.issues ?? [];
  const unsupportedClaimIssues = claimIssues.filter(
    (issue) => issue.issue === "unsupported_claim",
  );
  const postPrimerBridge = turns.find(
    (turn) => turn.turn_type === "post_primer_bridge",
  );
  const primerEnabled = props.episode?.definition.media?.opening?.enabled === true;
  const canCreatePostPrimerBridge = Boolean(
    props.episode &&
      !["COMPLETED", "CANCELLED"].includes(props.episode.status),
  );
  const canReopenApprovedTranscript = Boolean(
    transcript?.status === "approved" && canCreatePostPrimerBridge,
  );
  const [editingTurnId, setEditingTurnId] = React.useState<string | null>(null);
  const [draftText, setDraftText] = React.useState("");

  const beginEditing = (turn: (typeof turns)[number]) => {
    setEditingTurnId(turn.id);
    setDraftText(turn.text);
  };

  const cancelEditing = () => {
    setEditingTurnId(null);
    setDraftText("");
  };

  const saveTextEdit = (turn: (typeof turns)[number]) => {
    const text = draftText.trim();
    if (!text || turn.source_discussion_turn_ids.length === 0) {
      return;
    }
    props.onEditText(turn.source_discussion_turn_ids[0], text);
    cancelEditing();
  };

  return (
    <section className="transcriptPanel">
      <div className="sectionTitle">
        <h2>Transcript Review</h2>
        <span>
          {props.canEdit
            ? "Review required"
            : canReopenApprovedTranscript
              ? "Approved"
              : props.episode?.status ?? "No episode"}
        </span>
      </div>
      {canReopenApprovedTranscript ? (
        <div className="qcBanner warning">
          <strong>Approved transcript</strong>
          <span>
            Create an editable successor to change the discussion. The approved
            revision remains in the audit history; new speech and character
            performance clips will be created only after the successor is
            approved.
          </span>
          <button
            className="secondaryButton compact"
            disabled={props.actionPending}
            onClick={props.onReopenForEditing}
            type="button"
          >
            <History size={16} />
            <span>
              {props.actionPending
                ? "Creating editable revision"
                : "Create editable revision"}
            </span>
          </button>
        </div>
      ) : null}
      {primerEnabled ? (
        <div className={`qcBanner ${postPrimerBridge ? "pass" : "warning"}`}>
          <strong>Post-primer host bridge</strong>
          <span>
            {postPrimerBridge
              ? props.bridgeRevisionCreated
                ? "Bridge draft created. Edit or regenerate the first moderator turn below, then approve this transcript revision before releasing speech and character performance."
                : "Review this first moderator turn before releasing speech and character performance."
              : "This transcript predates the post-primer bridge contract. Create a revised discussion transcript before assembling a primer-led preview."}
          </span>
          {!postPrimerBridge && canCreatePostPrimerBridge ? (
            <button
              className="primaryButton compact"
              disabled={props.actionPending}
              onClick={props.onCreatePostPrimerBridge}
              type="button"
            >
              <Plus size={16} />
              <span>
                {props.actionPending ? "Creating bridge draft" : "Create bridge draft"}
              </span>
            </button>
          ) : null}
        </div>
      ) : null}
      {props.actionPending ? (
        <div aria-live="polite" className="transcriptActionStatus" role="status">
          Updating transcript revision...
        </div>
      ) : null}
      {props.bridgeRevisionCreated && !props.actionPending ? (
        <div aria-live="polite" className="transcriptActionStatus" role="status">
          A new transcript revision is ready for review. The first turn below is
          the post-primer host bridge.
        </div>
      ) : null}
      {durationQc ? (
        <div className={`qcBanner ${durationQc.status}`}>
          <strong>{durationQc.status}</strong>
          <span>
            Duration{" "}
            {Math.round(durationQc.details.estimated_duration_seconds ?? 0)}s ·
            target {Math.round(durationQc.details.target_duration_seconds ?? 0)}
            s · max{" "}
            {Math.round(durationQc.details.maximum_duration_seconds ?? 0)}s
          </span>
        </div>
      ) : null}
      {qc ? (
        <div className={`qcBanner ${qc.status}`}>
          <strong>{qc.status}</strong>
          <span>
            Semantic fidelity {Math.round((qc.score ?? 0) * 100)}% ·{" "}
            {qc.details.failure_count ?? 0} failures ·{" "}
            {qc.details.warning_count ?? 0} warnings
          </span>
        </div>
      ) : null}
      {claimQc ? (
        <div
          className={`qcBanner ${
            unsupportedClaimIssues.length > 0 ? "warning" : claimQc.status
          }`}
        >
          <strong>
            {unsupportedClaimIssues.length > 0
              ? "Claim-citation warnings"
              : "Claim-citation review"}
          </strong>
          <span>
            {claimQc.details.cited_claim_count ?? 0}/
            {claimQc.details.claim_count ?? 0} claims cited ·{" "}
            {claimQc.details.unsupported_claim_count ?? 0} need editorial review ·{" "}
            {claimQc.details.invalid_evidence_ref_count ?? 0} invalid references.
            {unsupportedClaimIssues.length > 0
              ? props.canEdit
                ? " Review the flagged statements below. Approving this transcript accepts the editorial decision and releases production."
                : " The approved transcript retains these editorial warnings for the production record."
              : ""}
          </span>
          {unsupportedClaimIssues.length > 0 ? (
            <ol className="claimWarningList">
              {unsupportedClaimIssues.map((issue, index) => {
                const turnNumber = issue.transcript_turn_id
                  ? transcriptTurnNumbers.get(issue.transcript_turn_id)
                  : undefined;
                return (
                  <li key={`${issue.transcript_turn_id ?? "claim"}-${index}`}>
                    <div>
                      <strong>
                        {turnNumber ? `Turn ${turnNumber}` : "Transcript statement"}
                      </strong>
                      {issue.claim_type ? (
                        <span>{issue.claim_type.replace(/_/g, " ")}</span>
                      ) : null}
                    </div>
                    <p>{issue.claim ?? "Unsupported claim"}</p>
                  </li>
                );
              })}
            </ol>
          ) : null}
        </div>
      ) : null}
      {turns.map((turn) => (
        <article
          className={`turnRow ${turn.status === "excluded" ? "excluded" : ""}`}
          key={turn.id}
        >
          <div className="turnHeader">
            <div>
              <strong>{turn.speaker_participant_id}</strong>
              <span>
                {turn.turn_type === "post_primer_bridge"
                  ? "Post-primer host bridge"
                  : turn.edit_type}
              </span>
            </div>
            <div className="turnActions">
              <button
                className="secondaryButton compact"
                disabled={
                  !props.canEdit ||
                  props.actionPending ||
                  turn.source_discussion_turn_ids.length === 0 ||
                  turn.status === "excluded"
                }
                onClick={() =>
                  props.onRegenerate(turn.source_discussion_turn_ids[0])
                }
                type="button"
              >
                <RefreshCw size={16} />
                Regenerate
              </button>
              <button
                className="secondaryButton compact"
                disabled={
                  !props.canEdit ||
                  props.actionPending ||
                  turn.source_discussion_turn_ids.length === 0 ||
                  turn.status === "excluded"
                }
                onClick={() => beginEditing(turn)}
                type="button"
              >
                <Pencil size={16} />
                Edit text
              </button>
              <button
                className="secondaryButton compact danger"
                disabled={
                  !props.canEdit ||
                  props.actionPending ||
                  turn.source_discussion_turn_ids.length === 0 ||
                  turn.status === "excluded"
                }
                onClick={() =>
                  props.onExclude(turn.source_discussion_turn_ids[0])
                }
                type="button"
              >
                <Trash2 size={16} />
                Exclude
              </button>
            </div>
          </div>
          {editingTurnId === turn.id ? (
            <div className="transcriptManualEdit">
              <textarea
                aria-label={`Edit ${turn.speaker_participant_id} turn text`}
                maxLength={12000}
                onChange={(event) => setDraftText(event.target.value)}
                value={draftText}
              />
              <div className="transcriptManualEditActions">
                <button
                  className="primaryButton compact"
                  disabled={props.actionPending || !draftText.trim()}
                  onClick={() => saveTextEdit(turn)}
                  type="button"
                >
                  <Save size={16} />
                  Save text
                </button>
                <button
                  className="secondaryButton compact"
                  disabled={props.actionPending}
                  onClick={cancelEditing}
                  type="button"
                >
                  Cancel
                </button>
              </div>
            </div>
          ) : (
            <p>
              {turn.status === "excluded"
                ? "Excluded from broadcast transcript."
                : turn.text}
            </p>
          )}
        </article>
      ))}
      {turns.length === 0 ? (
        <div className="emptyState">No broadcast transcript available.</div>
      ) : null}
    </section>
  );
}

function StageApprovalPanel(props: {
  title: string;
  description: string;
  approveLabel: string;
  rejectLabel: string;
  isPending: boolean;
  approveDisabled?: boolean;
  onApprove: () => void;
  onReject: () => void;
}) {
  return (
    <section className="stageApprovalPanel">
      <div>
        <span className="stepLabel">Next</span>
        <h3>{props.title}</h3>
        <p>{props.description}</p>
      </div>
      <div className="stageApprovalActions">
        <button
          className="primaryButton"
          disabled={props.isPending || props.approveDisabled}
          onClick={props.onApprove}
          type="button"
        >
          <CheckCircle2 size={18} />
          {props.isPending ? "Saving decision" : props.approveLabel}
        </button>
        <button
          className="secondaryButton danger"
          disabled={props.isPending}
          onClick={props.onReject}
          type="button"
        >
          <Ban size={18} />
          {props.rejectLabel}
        </button>
      </div>
    </section>
  );
}

function latestTranscriptQc(episode: Episode | null): QualityResult | null {
  if (!episode?.canonical_transcript_version_id) {
    return null;
  }
  const results = episode.quality_results.filter(
    (result) =>
      result.target_type === "transcript_version" &&
      result.target_id === episode.canonical_transcript_version_id &&
      result.check_type === "transcript_semantic_fidelity",
  );
  return results.length > 0 ? results[results.length - 1] : null;
}

function latestClaimCitationQcForTranscript(
  episode: Episode | null,
  transcript: Transcript | null | undefined,
): QualityResult | null {
  if (!transcript) {
    return null;
  }
  const results =
    episode?.quality_results.filter(
      (result) =>
        result.target_type === "transcript_version" &&
        result.target_id === transcript.id &&
        result.check_type === "claim_citation_integrity",
    ) ?? [];
  return results.length > 0 ? results[results.length - 1] : null;
}

function latestDurationQc(episode: Episode | null): QualityResult | null {
  const results =
    episode?.quality_results.filter(
      (result) =>
        result.target_type === "discussion_session" &&
        result.check_type === "discussion_duration_control",
    ) ?? [];
  return results.length > 0 ? results[results.length - 1] : null;
}

function Metric(props: {
  icon: React.ReactNode;
  label: string;
  value: number;
}) {
  return (
    <div className="metric">
      <div className="metricIcon">{props.icon}</div>
      <span>{props.label}</span>
      <strong>{props.value}</strong>
    </div>
  );
}

type RootElement = HTMLElement & { _dialecticoreRoot?: Root };

const rootElement = document.getElementById("root")! as RootElement;
const root = rootElement._dialecticoreRoot ?? ReactDOM.createRoot(rootElement);
rootElement._dialecticoreRoot = root;

root.render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <App />
    </QueryClientProvider>
  </React.StrictMode>,
);
